const cloud = { on: false, db: null, auth: null, users: [], usersFetchedAt: 0, states: {}, programs: {}, mesajlar: [], ayarlar: {} };

function cloudInit() {
  try {
    if (FIREBASE_CONFIG.apiKey && window.firebase) {
      firebase.initializeApp(FIREBASE_CONFIG);
      cloud.db = firebase.firestore();
      // Bazı tarayıcıların yerleşik VPN / veri sıkıştırma özellikleri (Opera VPN,
      // Yandex Turbo vb.) veya bazı ağlar, Firestore'un varsayılan "canlı akış"
      // bağlantısını bozup 400 hatası verdirebiliyor. Bu ayar, öyle bir durum
      // sezildiğinde otomatik olarak daha uyumlu bir bağlantı yöntemine geçer.
      // Firestore()'dan hemen sonra, başka hiçbir işlem yapılmadan çağrılmalı.
      try { cloud.db.settings({ experimentalAutoDetectLongPolling: true, merge: true }); } catch(e){}
      cloud.auth = firebase.auth();
      cloud.on = true;
      // Çevrimdışı kalıcılık: internet yokken yapılan kayıtları Firestore
      // kendi yerel deposunda (IndexedDB) biriktirir ve bağlantı geri
      // geldiğinde OTOMATİK olarak buluta gönderir. Bu işlemi ASLA
      // uygulamanın açılışını beklemeye almıyoruz — bazı ortamlarda
      // (örn. dosyayı doğrudan çift tıklayıp açmak) bu tamamlanmayabilir
      // ve daha önce açılışı buna bağlamak başlangıç ekranında sonsuza
      // kadar takılı kalmaya yol açıyordu.
      try {
        cloud.db.enablePersistence().catch(e => {
          console.warn('Çevrimdışı kalıcılık açılamadı:', e && e.code);
        });
      } catch(e) { console.warn('Çevrimdışı kalıcılık başlatılamadı:', e); }
    }
  } catch(e) { console.warn('Firebase başlatılamadı, yerel modda devam:', e); }
}

async function cloudRefreshUsers(zorla) {
  if (!cloud.on) return true;
  // Aynı oturumda arka arkaya (rol seçimi -> giriş/kayıt gibi) gelen çağrılar
  // her seferinde tüm öğrenci/veli listesini yeniden okumasın diye 1 dakikalık
  // bir önbellek kullanıyoruz. Bu, ücretsiz kotayı gereksiz yere tüketmeyi
  // engelliyor; yeni bir kayıt olduğunda liste zaten anında güncellenir
  // (bkz. doRegister), o yüzden tazelik kaybı olmaz.
  const ONBELLEK_MS = 60000;
  if (!zorla && cloud.users.length && (Date.now() - cloud.usersFetchedAt) < ONBELLEK_MS) return true;
  try {
    // Bağlantı çok yavaşsa/takılırsa bu işlem ekranı sonsuza kadar
    // bekletmesin diye bir güvenlik sınırı koyuyoruz (yavaş bağlantılara
    // toleranslı olsun diye 20 saniyeye çıkardık).
    const snap = await Promise.race([
      // { source: 'server' }: bu listenin GÜNCEL olması hayati (kimin kayıtlı
      // olduğunu belirliyor) — cihazın eski/önbelleklenmiş bir kopyasını değil,
      // her zaman doğrudan sunucudaki gerçek veriyi çekmesini zorunlu kılıyoruz.
      cloud.db.collection('users').get({ source: 'server' }),
      new Promise((_, rej) => setTimeout(() => rej(new Error('zaman aşımı')), 20000))
    ]);
    cloud.users = snap.docs.map(d => d.data());
    cloud.usersFetchedAt = Date.now();
    return true;
  } catch(e){ console.warn('Kullanıcılar çekilemedi:', e); return false; }
}
function cloudSaveUser(user) {
  if (!cloud.on) return Promise.resolve(true);
  // { merge: true }: states/{id} ile aynı sebep -- iki farklı cihaz/sekme aynı anda kullanıcı
  // profilini güncellerse, bayat bir kopya diğerinin az önce yazdığı alanı silmesin.
  return cloud.db.collection('users').doc(user.id).set(user, { merge: true })
    .then(() => true)
    .catch(e => { console.warn('Kullanıcı kaydı buluta yazılamadı:', e); return false; });
}
async function cloudLoadDoc(col, id) {
  if (!cloud.on) return null;
  try { const doc = await cloud.db.collection(col).doc(id).get(); return doc.exists ? doc.data() : null; }
  catch(e){ console.warn(e); return null; }
}
// Buluta yazma 1 saniye "debounce" edilir (her tuşta buluta gitmesin diye), ANCAK bu 1 saniyelik
// bekleme sırasında öğrenci/öğretmen ekranı değiştirir ya da uygulamayı kapatırsa, o son yazılan
// veri (ör. bir konuya girilen "yanlış" sayısı) buluta hiç ulaşmadan kaybolabiliyordu — cihazda
// doğru duruyordu ama bulut eski/eksik kopyayı koruyor, bir sonraki açılışta bulut kopyası yerelin
// üzerine yazıp o veriyi siliyordu. Bunu önlemek için: bekleyen her yazma burada saklanır ve
// cloudFlushAllPending() ile (sekme değişince / uygulama arka plana alınınca / çıkış yapılınca)
// 1 saniye beklemeden HEMEN gönderilir.
const cloudTimers = {};
const cloudPendingWrites = {};
function cloudSaveDocDebounced(col, id, data) {
  if (!cloud.on) return;
  const k = col + '/' + id;
  cloudPendingWrites[k] = { col, id, data };
  clearTimeout(cloudTimers[k]);
  cloudTimers[k] = setTimeout(() => cloudFlushOne(k), 1000);
}
// ⚠️ KRİTİK VERİ GÜVENLİĞİ NOTU: neden { merge: true }?
// saveState(), HER kayıtta öğrencinin TÜM state nesnesini (vg, kazanimlar, denemeler, sb, kisisel,
// student, ...) buluta yazar. Eğer öğrencinin cihazındaki uygulama uzun süre kapatılmadan açık
// kaldıysa (arka planda askıda), hafızadaki `state` nesnesi ESKİ bir andaki kopyayı tutabilir.
// Öğrenci sadece "Kişisel Bilgilerim" ekranında tek bir alanı (ör. başlangıç tarihini) değiştirip
// kaydettiğinde bile, saveState() o ESKİ/EKSİK `state.vg` nesnesini de buluta gönderiyordu ve eski
// kodda kullanılan sade .set(data) YENİ dokümanı TAMAMEN eskisinin üzerine yazıyordu -- bu da
// öğrencinin o ana kadar başka bir anda/cihazda girdiği Veri Girişi sayılarının (vg içindeki
// vgkz_... anahtarlarının) sessizce silinmesine yol açıyordu ("konu listeleri duruyor ama içindeki
// sayılar kayboluyor" hatası buradan kaynaklanıyordu).
// ÇÖZÜM: Firestore'un { merge: true } seçeneği, iç içe geçmiş obje (map) alanlarını -- vg,
// kazanimlar, sb.cevaplar, denemeler, sayac gibi -- ESKİ belgeyle DERİNLEMESİNE birleştirir: yeni
// yazılan anahtarlar güncellenir, ama yeni yazıda bulunmayan (yani cihazda henüz görünmeyen, başka
// bir yerde eklenmiş) eski anahtarlar SİLİNMEZ, korunur. Bu sayede "bayat" bir cihaz kopyası artık
// bulutta biriken daha güncel veriyi asla silemez. (Not: bu uygulamada hiçbir özellik bu obje
// alanlarından tek tek kayıt SİLMEZ -- sadece ekler/günceller -- bu yüzden merge:true burada
// güvenlidir; dizi alanları [ör. bildirimler, kavanoz.fotograflar] Firestore'da birleştirilmez,
// yazıldıklarında olduğu gibi değişir, ama bu zaten öncekiyle aynı davranıştır, bir gerileme değil.)
// ============================================================
//  🛟 OTOMATİK GÜNLÜK YEDEK (states_backup) — "kurtarma planı"
//  Bir öğrencinin verisi her buluta kaydedildiğinde (günde en fazla 1 kez, gereksiz yazma
//  trafiğini önlemek için), o anki TAM verinin bir kopyası AYRI bir koleksiyona (states_backup)
//  da yazılır. Haftanın 7 gününe (paz/pzt/sal/car/per/cum/cmt) göre SABİT 7 yuvaya yazıldığı için
//  otomatik olarak her zaman "son 7 günün" bir yedeği tutulur — bir hafta sonra o günün yuvası
//  kendiliğinden yeni bir yedekle değişir, ekstra silme/temizlik kodu hiç gerekmez.
//  ÇOK ÖNEMLİ GÜVENLİK KURALI: bu yedekleme kesinlikle "best effort"tur — yani içinde ne olursa
//  olsun (ağ hatası, beklenmeyen veri şekli, vs.) ANA kaydetme akışını asla etkilemez, asla
//  bekletmez (await edilmez, sonucunu kimse beklemez) ve asla bir hata fırlatmaz. Bu yüzden asıl
//  kaydetme (cloudFlushOne'daki normal .set) her zaman TAMAMEN bu fonksiyondan bağımsız çalışır;
//  yedekleme tamamen başarısız olsa bile öğrenci/öğretmen hiçbir şey fark etmez, uygulama normal
//  şekilde çalışmaya devam eder.
// ============================================================
const YEDEK_GUN_ADLARI = ['paz','pzt','sal','car','per','cum','cmt'];
const cloudYedekSonZaman = {}; // studentId -> son yedek alma zamanı (ms)
function cloudYedekAlBestEffort(studentId, data) {
  try {
    if (!cloud.on || !cloud.db || !studentId) return;
    const simdi = Date.now();
    const sonAlinan = cloudYedekSonZaman[studentId] || 0;
    if (simdi - sonAlinan < 6 * 60 * 60 * 1000) return; // aynı öğrenci için 6 saatten sık yedek almaya çalışma
    cloudYedekSonZaman[studentId] = simdi;
    const gun = YEDEK_GUN_ADLARI[new Date().getDay()];
    const yedekId = studentId + '_' + gun;
    let kopya;
    try { kopya = JSON.parse(JSON.stringify(data)); } catch(e) { return; }
    cloud.db.collection('states_backup').doc(yedekId).set({
      studentId: studentId, gun: gun, tarih: new Date().toISOString(), data: kopya
    }).catch(function(){ /* yedekleme başarısız olsa bile sessizce geç, ana akışı etkileme */ });
  } catch(e) { /* yedekleme fonksiyonu ASLA ana kaydetme akışını bozmamalı */ }
}

function cloudFlushOne(k) {
  const pending = cloudPendingWrites[k];
  if (!pending) return;
  clearTimeout(cloudTimers[k]);
  delete cloudTimers[k];
  delete cloudPendingWrites[k];
  cloud.db.collection(pending.col).doc(pending.id).set(JSON.parse(JSON.stringify(pending.data)), { merge: true }).catch(e => console.warn(e));
  // Yedekleme SADECE öğrenci "states" belgeleri için ve ana yazmadan tamamen bağımsız/ek olarak.
  if (pending.col === 'states') {
    try { cloudYedekAlBestEffort(pending.id, pending.data); } catch(e){}
  }
}
function cloudFlushAllPending() {
  Object.keys(cloudPendingWrites).forEach(k => cloudFlushOne(k));
}
// Sekme/uygulama arka plana alınınca (kapanmadan hemen önceki en güvenilir an) bekleyen
// yazmaları hemen gönder.
try {
  document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'hidden') cloudFlushAllPending(); });
  window.addEventListener('pagehide', cloudFlushAllPending);
} catch(e){}

// Bir öğrencinin YKS verisini oku (buluttan ya da yerelden)
function getStudentState(id) {
  if (cloud.on) return cloud.states[id] || null;
  try { return JSON.parse(vgGetItem('ykspusulam_' + id) || 'null'); } catch(e){ return null; }
}

// ============================================================
//  MESAJLAŞMA (Veli ↔ Rehber Öğretmen ↔ Öğrenci)
// ============================================================
const MESAJLAR_KEY = 'ykspusulam_mesajlar';

function getMesajlar() {
  if (cloud.on) return cloud.mesajlar || [];
  try { return JSON.parse(vgGetItem(MESAJLAR_KEY) || '[]'); } catch(e){ return []; }
}
function saveMesajlar(list) {
  if (cloud.on) { cloud.mesajlar = list; } else { vgSetItem(MESAJLAR_KEY, JSON.stringify(list)); }
}
async function cloudRefreshMesajlar() {
  if (!cloud.on || !currentUser) return;
  try {
    // Güvenlik kuralları her mesajın sadece gönderen/alıcı tarafından
    // okunmasına izin verdiği için, tüm koleksiyonu değil sadece kendi
    // mesajlarımızı iki ayrı sorguyla çekiyoruz.
    const uid = currentUser.id;
    const [gidenSnap, gelenSnap] = await Promise.all([
      cloud.db.collection('mesajlar').where('fromId', '==', uid).get(),
      cloud.db.collection('mesajlar').where('toId', '==', uid).get()
    ]);
    const map = {};
    gidenSnap.docs.forEach(d => { map[d.id] = d.data(); });
    gelenSnap.docs.forEach(d => { map[d.id] = d.data(); });
    cloud.mesajlar = Object.values(map);
  } catch(e){ console.warn('Mesajlar çekilemedi:', e); }
}
function cloudSaveMesaj(mesaj) {
  if (!cloud.on) return;
  cloud.db.collection('mesajlar').doc(mesaj.id).set(mesaj).catch(e => console.warn(e));
}

function mesajGonder(aliciId, aliciRole, aliciName, metin) {
  metin = (metin || '').trim();
  if (!metin || !aliciId) return false;
  // Veli ↔ Öğrenci doğrudan mesajlaşması kaldırıldı; tüm iletişim rehber öğretmen üzerinden.
  const yasakli = (currentUser.role === 'veli' && aliciRole === 'ogrenci') ||
                  (currentUser.role === 'ogrenci' && aliciRole === 'veli');
  if (yasakli) return false;
  const list = getMesajlar();
  const mesaj = {
    id: 'm' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
    fromId: currentUser.id, fromRole: currentUser.role, fromName: currentUser.name,
    toId: aliciId, toRole: aliciRole, toName: aliciName,
    mesaj: metin, tarih: Date.now(), okundu: false
  };
  list.push(mesaj);
  if (cloud.on) { cloudSaveMesaj(mesaj); } else { saveMesajlar(list); }
  return true;
}
function mesajKutusu(tip) {
  // tip: 'gelen' | 'giden'
  const list = getMesajlar();
  return list
    .filter(m => tip === 'gelen' ? m.toId === currentUser.id : m.fromId === currentUser.id)
    .sort((a,b) => b.tarih - a.tarih);
}
function mesajOkunmamisSayisi() {
  return getMesajlar().filter(m => m.toId === currentUser.id && !m.okundu).length;
}
function mesajlariOkunduIsaretle() {
  const list = getMesajlar();
  let degisti = false;
  list.forEach(m => { if (m.toId === currentUser.id && !m.okundu) { m.okundu = true; degisti = true; } });
  if (degisti) {
    if (cloud.on) { list.forEach(m => { if (m.toId === currentUser.id) cloudSaveMesaj(m); }); }
    else { saveMesajlar(list); }
  }
}
// Rol bazlı: bu kullanıcının mesaj gönderebileceği kişiler
function mesajAliciListesi() {
  const users = getUsers();
  if (currentUser.role === 'veli') {
    const teacher = users.find(u => u.id === currentUser.teacherId);
    const liste = [];
    if (teacher) liste.push({ id: teacher.id, role: 'ogretmen', name: teacher.name, etiket: '🧑\u200d🏫 Rehber Öğretmen (' + teacher.name + ')' });
    return liste;
  }
  if (currentUser.role === 'ogretmen') {
    const ogrenciler = users.filter(u => u.role === 'ogrenci' && u.teacherId === currentUser.id);
    const liste = [];
    ogrenciler.forEach(o => {
      liste.push({ id: o.id, role: 'ogrenci', name: o.name, etiket: '🎓 ' + o.name + ' (Öğrenci)' });
      const veli = users.find(v => v.role === 'veli' && v.studentId === o.id);
      if (veli) liste.push({ id: veli.id, role: 'veli', name: veli.name, etiket: '👨\u200d👩\u200d👧 ' + veli.name + ' (' + o.name + '\'in Velisi)' });
    });
    return liste;
  }
  if (currentUser.role === 'ogrenci') {
    const liste = [];
    if (currentUser.teacherId) {
      const teacher = users.find(u => u.id === currentUser.teacherId);
      if (teacher) liste.push({ id: teacher.id, role: 'ogretmen', name: teacher.name, etiket: '🧑\u200d🏫 Rehber Öğretmen (' + teacher.name + ')' });
    }
    return liste;
  }
  return [];
}

// ============================================================
//  KULLANICI / OTURUM SİSTEMİ (AUTH)
// ============================================================
const USERS_KEY = 'ykspusulam_users';
const SESSION_KEY = 'ykspusulam_session';
let authRole = null; // 'ogrenci' | 'veli' | 'ogretmen'
let currentUser = null;

function getUsers() {
  if (cloud.on) return cloud.users;
  try { return JSON.parse(vgGetItem(USERS_KEY) || '[]'); } catch(e){ return []; }
}
function saveUsers(users) {
  vgSetItem(USERS_KEY, JSON.stringify(users));
}
function normalizePhone(p) { return (p || '').replace(/\D/g, ''); }

function simpleHash(str) {
  // Basit hash (gerçek bir sunucu olmadığı için temel koruma amaçlı)
  let h = 5381;
  for (let i = 0; i < str.length; i++) { h = ((h << 5) + h) ^ str.charCodeAt(i); }
  return 'h' + (h >>> 0).toString(36);
}

// Öğrenci kodu: veli kaydında öğretmen/öğrenci listesi göstermek yerine
// öğrencinin kendi kodunu paylaşmasını sağlayan, benzersiz kısa kod.
function generateStudentCode(users) {
  const harfler = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; // karışabilecek 0/O, 1/I gibi karakterler çıkarıldı
  let kod;
  do {
    kod = 'YKS-';
    for (let i = 0; i < 4; i++) kod += harfler[Math.floor(Math.random() * harfler.length)];
  } while (users.some(u => u.kod === kod));
  return kod;
}
// Eski (kodsuz) öğrenci hesapları için kod üretip kalıcı hale getirir.
function ensureStudentKod(user) {
  if (!user || user.role !== 'ogrenci' || user.kod) return user && user.kod;
  const users = getUsers();
  const kayitli = users.find(u => u.id === user.id);
  if (!kayitli) return null;
  kayitli.kod = generateStudentCode(users);
  user.kod = kayitli.kod;
  if (cloud.on) { cloudSaveUser(kayitli); } else { saveUsers(users); }
  return kayitli.kod;
}

const ROLE_META = {
  ogrenci:  { icon: '🎓', ad: 'Öğrenci' },
  veli:     { icon: '👨‍👩‍👧', ad: 'Veli' },
  ogretmen: { icon: '🧑‍🏫', ad: 'Rehber Öğretmen' }
};

function showAuthStep(id) {
  ['stepRole','stepChoice','stepRegister','stepLogin'].forEach(s => {
    document.getElementById(s).style.display = (s === id) ? 'block' : 'none';
  });
  document.getElementById('regError').textContent = '';
  document.getElementById('loginError').textContent = '';
}

function selectRole(role) {
  authRole = role;
  cloudRefreshUsers(); // arka planda çalışır, ekran geçişini ASLA beklemez
  const m = ROLE_META[role];
  document.getElementById('choiceIcon').textContent = m.icon;
  document.getElementById('choiceTitle').textContent = m.ad;
  showAuthStep('stepChoice');
}

function getOrCreateGuestId() {
  let gid = vgGetItem('ykspusulam_guest_id');
  if (!gid) {
    gid = 'misafir-' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
    vgSetItem('ykspusulam_guest_id', gid);
  }
  return gid;
}

// Misafir Girişi: kayıt/giriş adımları tamamen atlanır, uygulamaya
// doğrudan öğrenci yetkisiyle (tüm sekme ve özelliklere erişimle) girilir.
async function guestLogin() {
  authRole = 'ogrenci';
  currentUser = {
    id: getOrCreateGuestId(),
    role: 'ogrenci',
    name: 'Misafir Kullanıcı',
    email: '', phone: '',
    teacherId: null, studentId: null,
    guest: true
  };
  document.getElementById('authScreen').style.display = 'none';
  if (cloud.on) {
    try { cloud.states[currentUser.id] = await cloudLoadDoc('states', currentUser.id); } catch(e){}
  }
  loadState();
  if (!state.sb) state.sb = sbVarsayilanState();
  sbState = state.sb;
  if (!state.student.name) state.student.name = 'Misafir Kullanıcı';
  showApp();
}

function backToRole() { authRole = null; showAuthStep('stepRole'); }
function backToChoice() { showAuthStep('stepChoice'); }

function showRegister() {
  // Buluta (Firebase) erişim yoksa yeni hesap açılmasına izin verilmez: yerelde
  // oluşturulan bir hesap hiçbir cihazla/rehber öğretmenle senkronize olmaz ve
  // veri kaybı riskini artırır. Bu yüzden erişim yoksa kayıt formu hiç açılmaz.
  if (!cloud.on) {
    alert('Şu anda internet/bulut bağlantısı sağlanamıyor, bu yüzden yeni hesap açılamıyor. Lütfen internet bağlantını kontrol edip tekrar dene.');
    return;
  }
  const m = ROLE_META[authRole];
  document.getElementById('regTitle').textContent = m.icon + ' ' + m.ad + ' Kayıt';
  const studentWrap = document.getElementById('regStudentWrap');
  studentWrap.style.display = (authRole === 'veli') ? 'block' : 'none';
  ['regName','regEmail','regPhone','regPass'].forEach(i => document.getElementById(i).value = '');
  if (authRole === 'veli') {
    document.getElementById('regStudentKod').value = '';
    document.getElementById('regStudentName').value = '';
  }
  showAuthStep('stepRegister');
}

function showLogin() {
  const m = ROLE_META[authRole];
  document.getElementById('loginTitle').textContent = m.icon + ' ' + m.ad + ' Giriş';
  document.getElementById('loginId').value = '';
  document.getElementById('loginPass').value = '';
  document.getElementById('loginRemember').checked = false;
  showAuthStep('stepLogin');
}

async function doRegister() {
  // İkinci bir güvenlik katmanı: showRegister() zaten bulut yokken formu açtırmıyor,
  // ama doRegister() doğrudan çağrılsa bile burada da aynı kural uygulanır.
  if (!cloud.on) {
    document.getElementById('regError').textContent = 'İnternet/bulut bağlantısı olmadan yeni hesap açılamaz. Lütfen bağlantını kontrol edip tekrar dene.';
    return;
  }
  await cloudRefreshUsers();
  const name  = document.getElementById('regName').value.trim();
  const email = document.getElementById('regEmail').value.trim().toLowerCase();
  const phone = normalizePhone(document.getElementById('regPhone').value);
  const pass  = document.getElementById('regPass').value;
  const err = document.getElementById('regError');

  if (!name)  { err.textContent = 'Lütfen ad soyad gir.'; return; }
  if (!email || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) { err.textContent = 'Geçerli bir e-posta adresi gir.'; return; }
  if (!phone || phone.length < 10) { err.textContent = 'Geçerli bir cep telefonu gir (en az 10 hane).'; return; }
  if (!pass || pass.length < 6) { err.textContent = 'Şifre en az 6 karakter olmalı.'; return; }

  const users = getUsers();
  if (users.some(u => u.email === email)) { err.textContent = 'Bu e-posta ile kayıtlı bir hesap zaten var.'; return; }
  if (users.some(u => u.phone === phone)) { err.textContent = 'Bu telefon ile kayıtlı bir hesap zaten var.'; return; }

  // Tek bir rehber öğretmen olduğu için öğrenciler otomatik olarak ona bağlanır.
  const ogretmen = users.find(u => u.role === 'ogretmen');
  let teacherId = null;
  let studentId = null;

  if (authRole === 'ogrenci') {
    teacherId = ogretmen ? ogretmen.id : null;
  } else if (authRole === 'veli') {
    const kod = document.getElementById('regStudentKod').value.trim().toUpperCase();
    const adGirilen = document.getElementById('regStudentName').value.trim();
    if (!kod) { err.textContent = 'Lütfen öğrenci kodunu gir.'; return; }
    if (!adGirilen) { err.textContent = 'Lütfen öğrencinin adını soyadını gir.'; return; }
    const ogrenci = users.find(u => u.role === 'ogrenci' && u.kod === kod);
    if (!ogrenci) { err.textContent = 'Bu koda sahip bir öğrenci bulunamadı. Kodu kontrol et.'; return; }
    if (ogrenci.name.trim().toLocaleUpperCase('tr-TR') !== adGirilen.toLocaleUpperCase('tr-TR')) {
      err.textContent = 'Öğrenci kodu ile girdiğin ad soyad eşleşmiyor.'; return;
    }
    if (!ogrenciAyariGetir(ogrenci.id, 'appAcik')) {
      err.textContent = 'Bu öğrenci için rehber öğretmen erişimi kapattı. Lütfen daha sonra tekrar dene.'; return;
    }
    studentId = ogrenci.id;
    teacherId = ogrenci.teacherId || (ogretmen ? ogretmen.id : null);
  }

  // Bulut açıksa gerçek bir Firebase hesabı oluştur; kimliğimiz (id) Firebase'in
  // verdiği güvenli kimlik (uid) olur. Böylece kimse başkasının verisini
  // "tahmin ederek" okuyamaz — sadece kendi şifresiyle giriş yapan kişi erişebilir.
  let uid = 'u' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
  if (cloud.on) {
    try {
      const cred = await Promise.race([
        cloud.auth.createUserWithEmailAndPassword(email, pass),
        new Promise((_, rej) => setTimeout(() => rej({ code: 'zaman-asimi' }), 15000))
      ]);
      uid = cred.user.uid;
    } catch (e) {
      if (e && e.code === 'auth/email-already-in-use') { err.textContent = 'Bu e-posta ile kayıtlı bir hesap zaten var.'; }
      else if (e && e.code === 'auth/weak-password') { err.textContent = 'Şifre en az 6 karakter olmalı.'; }
      else if (e && e.code === 'auth/invalid-email') { err.textContent = 'Geçerli bir e-posta adresi gir.'; }
      else if (e && e.code === 'auth/operation-not-allowed') { err.textContent = 'Firebase\'de "E-posta/Şifre" girişi henüz açılmamış görünüyor. Authentication > Sign-in method bölümünden açman gerekiyor.'; }
      else if (e && e.code === 'zaman-asimi') { err.textContent = 'Bağlantı çok yavaş kaldı (15 sn). İnternetini kontrol edip tekrar dene.'; }
      else { err.textContent = 'Kayıt olurken bir bağlantı sorunu oluştu: ' + ((e && (e.code || e.message)) || 'bilinmeyen hata') + '. İnternetini kontrol edip tekrar dene.'; }
      return;
    }
  }

  const user = {
    id: uid,
    role: authRole,
    name, email, phone,
    pass: simpleHash(pass),
    teacherId: teacherId || null,
    studentId: studentId,
    createdAt: Date.now()
  };
  if (authRole === 'ogrenci') user.kod = generateStudentCode(users);
  users.push(user);
  if (cloud.on) {
    // Yazma işleminin GERÇEKTEN buluta ulaştığından emin oluyoruz — daha önce
    // bu sessizce başarısız olup kullanıcıya hiç haber verilmiyordu, bu yüzden
    // kişi "kayıt oldum" sanıp aslında bulutta hiç kaydı olmadan devam ediyordu.
    const basarili = await cloudSaveUser(user);
    if (!basarili) {
      users.pop();
      err.textContent = 'Kayıt buluta yazılamadı. İnternet bağlantını kontrol edip tekrar dene. (Sorun devam ederse ekran görüntüsü at.)';
      return;
    }
  } else {
    saveUsers(users);
  }
  oturumKaydet(user.id, true); // yeni kayıtta oturum varsayılan olarak açık tutulur
  currentUser = user;
  enterApp();
}

// "Şifremi Unuttum": Firebase'in kendi e-posta ile şifre sıfırlama sistemini
// kullanır. Kullanıcı e-postasına gelen bağlantıya tıklayıp yeni bir şifre
// belirler; bizim tarafımızda ekstra bir şey yapmaya gerek kalmaz, çünkü
// gerçek giriş kontrolü artık tamamen Firebase Authentication üzerinden.
async function sifremiUnuttum() {
  const err = document.getElementById('loginError');
  err.style.color = '';
  if (!cloud.on) {
    err.textContent = 'Bu özellik sadece internet bağlantısı ile çalışır.';
    return;
  }
  const idRaw = (document.getElementById('loginId').value || '').trim().toLowerCase();
  if (!idRaw || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(idRaw)) {
    err.textContent = 'Önce üstteki kutuya e-posta adresini yaz, sonra "Şifremi Unuttum"a bas.';
    return;
  }
  try {
    await cloud.auth.sendPasswordResetEmail(idRaw);
    err.style.color = 'green';
    err.textContent = '"' + idRaw + '" adresine bir şifre sıfırlama bağlantısı gönderildi. E-postanı (spam/gereksiz klasörü dahil) kontrol et.';
  } catch (e) {
    if (e && e.code === 'auth/user-not-found') {
      // Güvenlik için: e-postanın kayıtlı olup olmadığını ele vermeyelim, aynı mesajı göster.
      err.style.color = 'green';
      err.textContent = 'Eğer bu e-posta kayıtlıysa, bir şifre sıfırlama bağlantısı gönderildi.';
    } else {
      err.textContent = 'Bağlantı gönderilemedi: ' + ((e && (e.code || e.message)) || 'bilinmeyen hata');
    }
  }
}
async function doLogin() {
  const listeGeldi = await cloudRefreshUsers();
  const idRaw = document.getElementById('loginId').value.trim();
  const pass  = document.getElementById('loginPass').value;
  const err   = document.getElementById('loginError');
  if (!idRaw || !pass) { err.textContent = 'Tüm alanları doldur.'; return; }

  const idEmail = idRaw.toLowerCase();
  const idPhone = normalizePhone(idRaw);
  const users = getUsers();
  const user = users.find(u =>
    u.role === authRole &&
    (u.email === idEmail || (idPhone.length >= 10 && u.phone === idPhone))
  );
  if (!user) {
    if (cloud.on && listeGeldi === false) {
      err.textContent = 'Bağlantı yavaş/başarısız oldu, bu yüzden kayıt bulunamadı. İnternetini kontrol edip tekrar dene (hesabın muhtemelen duruyor).';
    } else {
      err.textContent = 'Bu bilgilerle kayıtlı ' + ROLE_META[authRole].ad.toLowerCase() + ' bulunamadı.';
    }
    return;
  }
  // Bulut açıkken şifre doğrulaması SADECE gerçek Firebase hesabı üzerinden
  // yapılır (aşağıda). Yerel kopyadaki eski şifre karşılaştırması kullanılmaz,
  // çünkü "şifremi unuttum" ile şifre değiştirildiğinde bu yerel kopya artık
  // güncel olmayabilir. Bulut kapalıyken (yerel/test modu) eski kontrol geçerli.
  if (!cloud.on && user.pass !== simpleHash(pass)) { err.textContent = 'Şifre hatalı.'; return; }
  // Bulut açıksa gerçek Firebase hesabıyla da giriş yap; böylece Firestore
  // güvenlik kuralları bu kişinin gerçekten kendisi olduğunu doğrulayabilir.
  if (cloud.on) {
    try {
      await Promise.race([
        cloud.auth.signInWithEmailAndPassword(user.email, pass),
        new Promise((_, rej) => setTimeout(() => rej({ code: 'zaman-asimi' }), 15000))
      ]);
    }
    catch (e) {
      if (e && e.code === 'zaman-asimi') { err.textContent = 'Bağlantı çok yavaş kaldı (15 sn). İnternetini kontrol edip tekrar dene.'; }
      else if (e && e.code === 'auth/operation-not-allowed') { err.textContent = 'Firebase\'de "E-posta/Şifre" girişi henüz açılmamış görünüyor.'; }
      else if (e && (e.code === 'auth/wrong-password' || e.code === 'auth/invalid-credential')) { err.textContent = 'Şifre hatalı.'; }
      else { err.textContent = 'Şifre hatalı ya da bağlantı sorunu: ' + ((e && (e.code || e.message)) || ''); }
      return;
    }
  }
  const ilgiliOgrenciId = authRole === 'ogrenci' ? user.id : (authRole === 'veli' ? user.studentId : null);
  if (ilgiliOgrenciId && !ogrenciAyariGetir(ilgiliOgrenciId, 'appAcik')) {
    err.textContent = 'Rehber öğretmen bu hesap için uygulama erişimini kapattı. Lütfen daha sonra tekrar dene.';
    return;
  }

  const acikTut = !!(document.getElementById('loginRemember') && document.getElementById('loginRemember').checked);
  oturumKaydet(user.id, acikTut);
  currentUser = user;
  enterApp();
}

// "Oturumu açık tut" işaretliyse localStorage'a (tarayıcı kapansa da kalır),
// işaretli değilse sessionStorage'a (sekme/tarayıcı kapanınca silinir) yazar.
function oturumKaydet(userId, acikTut) {
  try {
    if (acikTut) {
      vgSetItem(SESSION_KEY, userId);
      sessionStorage.removeItem(SESSION_KEY);
    } else {
      sessionStorage.setItem(SESSION_KEY, userId);
      vgRemoveItem(SESSION_KEY);
    }
  } catch(e){}
}

function logout() {
  try { cloudFlushAllPending(); } catch(e){}
  try { vgRemoveItem(SESSION_KEY); sessionStorage.removeItem(SESSION_KEY); } catch(e){}
  if (cloud.on && cloud.auth) { try { cloud.auth.signOut(); } catch(e){} }
  currentUser = null;
  authRole = null;
  document.getElementById('mainApp').classList.remove('active');
  document.getElementById('setupScreen').style.display = 'none';
  document.getElementById('rolePanel') && (document.getElementById('rolePanel').style.display = 'none');
  document.getElementById('authScreen').style.display = 'block';
  showAuthStep('stepRole');
}
// Native window.confirm() bazı Android/WebView paketleyicilerinde (ör. Median.co)
// hiçbir uyarı göstermeden otomatik "tamam" kabul edilebiliyor; bu yüzden kendi
// ekranımızda bir onay penceresi çiziyoruz — böylece her ortamda garanti çalışır.
function appModalKapat() {
  const el = document.getElementById('appModalRoot');
  if (el) el.remove();
}
function appConfirm(baslik, mesaj, evetMetin, onYes) {
  appModalKapat();
  const wrap = document.createElement('div');
  wrap.id = 'appModalRoot';
  wrap.className = 'appModalOverlay';
  wrap.innerHTML = `
    <div class="appModalBox">
      <div class="appModalTitle">${baslik}</div>
      <div class="appModalText">${mesaj}</div>
      <div class="appModalBtnRow">
        <button class="appModalBtn ghost" onclick="appModalKapat()">Vazgeç</button>
        <button class="appModalBtn danger" id="appModalYesBtn">${evetMetin}</button>
      </div>
    </div>`;
  document.body.appendChild(wrap);
  wrap.addEventListener('click', (e) => { if (e.target === wrap) appModalKapat(); });
  document.getElementById('appModalYesBtn').onclick = () => { appModalKapat(); onYes(); };
}
function cikisOnayla() {
  appConfirm('🚪 Çıkış Yap', 'Uygulamadan çıkış yapmak istediğine emin misin?', 'Evet, Çıkış Yap', logout);
}

// ============================================================
//  🎨 ARAYÜZ MODLARI — Premium (varsayılan) · Canlı · Soft · Aksiyon
//  Seçim: Ayarlar (⚙️) penceresinden. Cihazda localStorage'a, hesapta state.arayuzModu'na yazılır
//  (böylece öğrencinin başka cihazında da aynı mod açılır). Görünüm CSS'i index.html'de
//  html[data-mod="canli|soft|aksiyon"] altındadır; Premium'da öznitelik yoktur.
// ============================================================
const ARAYUZ_MOD_KEY = 'ykspusulam_arayuz_modu';
const ARAYUZ_MODLAR = {
  premium: { ad: 'Premium', ikon: '👑', aciklama: 'Koyu lacivert ve altın; zengin, klasik görünüm.', renkler: ['#232e4a', '#e6b84f', '#f6e4ab'] },
  canli:   { ad: 'Canlı',   ikon: '🌈', aciklama: 'Canlı renkler, daha sade ve net bir arayüz.',       renkler: ['#3b5bff', '#ff7a1a', '#12b76a'] },
  soft:    { ad: 'Soft',    ikon: '🌸', aciklama: 'Yumuşak pastel tonlar, sakin ve sade bir arayüz.',  renkler: ['#c7bcff', '#f6b6cf', '#bfe8d3'] },
  aksiyon: { ad: 'Aksiyon', ikon: '⚔️', aciklama: 'Mücadele, savaş ve zafer teması; kızıl ve altın.',  renkler: ['#14161d', '#e5383b', '#f5b301'] }
};
// Ana sayfa simgeleri (Premium resim kullanır; diğer modlar sade emoji)
const ARAYUZ_IKONLAR = {
  canli: { kisiselBilgiler:'👤', dersProgramim:'📅', veriGirisi:'✏️', konuVideolari:'🎬', sorubankasi:'📝', denemelerim:'📋', grafik:'📈', dersSayaci:'⏳', soruKavanozu:'💡', mesajlarim:'💬', yksNedir:'❓', meslekKesif:'🧭', egitselOyunlar:'🎮' },
  aksiyon: { kisiselBilgiler:'🛡️', dersProgramim:'🗺️', veriGirisi:'📜', konuVideolari:'🏕️', sorubankasi:'🏹', denemelerim:'⚔️', grafik:'🎯', dersSayaci:'🔥', soruKavanozu:'💣', mesajlarim:'📯', yksNedir:'🏰', meslekKesif:'👑', egitselOyunlar:'🏆' }
};
ARAYUZ_IKONLAR.soft = ARAYUZ_IKONLAR.canli;
const ARAYUZ_RENKLER = {
  canli: [['#3b82f6','#1d4ed8'], ['#fb923c','#ea580c'], ['#34d399','#059669'], ['#a78bfa','#7c3aed'], ['#f472b6','#db2777'], ['#22d3ee','#0891b2'], ['#fbbf24','#d97706'], ['#f87171','#dc2626']],
  soft:  [['#e0e7ff'], ['#fce7f3'], ['#dcfce7'], ['#fef3c7'], ['#ffe4e6'], ['#cffafe'], ['#ede9fe'], ['#ffedd5']],
  aksiyon: [['#e5383b'], ['#f5b301'], ['#ff7a2f'], ['#aeb4c6']]
};
function arayuzModuGecerli(m) { return (m && Object.prototype.hasOwnProperty.call(ARAYUZ_MODLAR, m)) ? m : 'premium'; }
function arayuzModuOku() {
  try { return arayuzModuGecerli(localStorage.getItem(ARAYUZ_MOD_KEY)); } catch (e) { return 'premium'; }
}
// O anda ekranda uygulanan mod
function arayuzModuAktif() {
  const a = document.documentElement.getAttribute('data-mod');
  return arayuzModuGecerli(a);
}
function arayuzModuUygula(mod) {
  mod = arayuzModuGecerli(mod);
  const h = document.documentElement;
  if (mod === 'premium') h.removeAttribute('data-mod'); else h.setAttribute('data-mod', mod);
  try { localStorage.setItem(ARAYUZ_MOD_KEY, mod); } catch (e) {}
  return mod;
}
function arayuzModuSec(mod) {
  mod = arayuzModuUygula(mod);
  try { if (typeof state === 'object' && state) { state.arayuzModu = mod; saveState(); } } catch (e) {}
  arayuzAyarPaneliAc(true);
  // Ana sayfadaysa simgeleri yeni moda göre yeniden çiz
  try {
    const app = document.getElementById('mainApp');
    if (app && app.classList.contains('active') && state && state.currentTab === 'dashboard') renderTab('dashboard');
  } catch (e) {}
}
function arayuzAyarPaneliAc(yenile) {
  appModalKapat();
  const aktif = arayuzModuAktif();
  const secenekler = Object.keys(ARAYUZ_MODLAR).map(k => {
    const m = ARAYUZ_MODLAR[k];
    return `<button type="button" class="mod-secenek${k === aktif ? ' aktif' : ''}" onclick="arayuzModuSec('${k}')">
      <div class="mod-renkler">${m.renkler.map(c => `<span style="background:${c}"></span>`).join('')}</div>
      <div style="min-width:0;"><div class="mod-ad">${m.ikon} ${m.ad}</div><div class="mod-acik">${m.aciklama}</div></div>
      ${k === aktif ? '<div class="mod-tik">✓</div>' : ''}
    </button>`;
  }).join('');
  const wrap = document.createElement('div');
  wrap.id = 'appModalRoot';
  wrap.className = 'appModalOverlay';
  wrap.innerHTML = `
    <div class="appModalBox" style="max-width:420px;">
      <div class="appModalTitle">⚙️ Ayarlar</div>
      <div style="font-weight:800;font-size:0.92rem;margin-bottom:10px;">🎨 Arayüz Modu</div>
      ${secenekler}
      <button class="appModalBtn ghost" style="width:100%;margin-top:4px;" onclick="appModalKapat()">Kapat</button>
    </div>`;
  document.body.appendChild(wrap);
  wrap.addEventListener('click', (e) => { if (e.target === wrap) appModalKapat(); });
}
// Ana sayfa menü simgesi (Premium: resim; diğer modlar: emoji) + kutucuğun renk değişkenleri
function arayuzMenuSimgesi(id, ad, i, mod) {
  if (mod === 'premium' || !ARAYUZ_IKONLAR[mod]) {
    return { stil: '', html: `<img class="pusula-menu-icon" src="${PUSULA_ICONS[id]}" alt="${ad}" style="animation-delay:${(i * 0.18).toFixed(2)}s">` };
  }
  const r = ARAYUZ_RENKLER[mod][i % ARAYUZ_RENKLER[mod].length];
  const stil = mod === 'canli' ? `--tc:${r[0]};--tc2:${r[1]};` : `--tc:${r[0]};`;
  return { stil, html: `<div class="pusula-emoji">${ARAYUZ_IKONLAR[mod][id] || '⭐'}</div>` };
}

// ---------- Profil paneli (avatar tıklanınca): ad/e-posta/telefon + şifre değiştirme ----------
function profilPanelAc() {
  if (!currentUser) return;
  appModalKapat();
  const row = (l, v) => `<div class="appModalRow"><span>${l}</span><span>${(v === undefined || v === null || v === '') ? '—' : v}</span></div>`;
  const wrap = document.createElement('div');
  wrap.id = 'appModalRoot';
  wrap.className = 'appModalOverlay';
  wrap.innerHTML = `
    <div class="appModalBox" style="max-width:420px;">
      <div class="appModalTitle">👤 Profil Bilgilerim</div>
      <div style="margin-bottom:18px;">
        ${row('Ad Soyad', currentUser.name)}
        ${row('E-posta', currentUser.email)}
        ${row('Telefon', currentUser.phone)}
      </div>
      <div style="font-weight:800;font-size:0.92rem;margin-bottom:8px;">🔒 Şifreni Değiştir</div>
      <input autocomplete="off" type="password" id="pfEskiSifre" class="appModalInput" placeholder="Mevcut şifren">
      <input autocomplete="off" type="password" id="pfYeniSifre" class="appModalInput" placeholder="Yeni şifre (en az 6 karakter)">
      <input autocomplete="off" type="password" id="pfYeniSifreTekrar" class="appModalInput" placeholder="Yeni şifre (tekrar)">
      <div id="pfSifreMsg" style="font-size:0.8rem;margin-bottom:10px;min-height:16px;"></div>
      <button class="appModalBtn primary" style="width:100%;" onclick="profilSifreDegistir()">Şifreyi Güncelle</button>
      <button class="appModalBtn ghost" style="width:100%;margin-top:10px;" onclick="appModalKapat()">Kapat</button>
    </div>`;
  document.body.appendChild(wrap);
  wrap.addEventListener('click', (e) => { if (e.target === wrap) appModalKapat(); });
}

async function profilSifreDegistir() {
  const msg = document.getElementById('pfSifreMsg');
  msg.style.color = 'var(--red)';
  const eski = document.getElementById('pfEskiSifre').value;
  const yeni = document.getElementById('pfYeniSifre').value;
  const yeniTekrar = document.getElementById('pfYeniSifreTekrar').value;
  if (!eski || !yeni || !yeniTekrar) { msg.textContent = 'Tüm alanları doldur.'; return; }
  if (yeni.length < 6) { msg.textContent = 'Yeni şifre en az 6 karakter olmalı.'; return; }
  if (yeni !== yeniTekrar) { msg.textContent = 'Yeni şifreler birbiriyle uyuşmuyor.'; return; }

  const users = getUsers();
  const idx = users.findIndex(u => u.id === currentUser.id);
  if (idx === -1) { msg.textContent = 'Kullanıcı bulunamadı.'; return; }

  if (cloud.on && cloud.auth && cloud.auth.currentUser) {
    try {
      const cred = firebase.auth.EmailAuthProvider.credential(currentUser.email, eski);
      await cloud.auth.currentUser.reauthenticateWithCredential(cred);
      await cloud.auth.currentUser.updatePassword(yeni);
    } catch (e) {
      if (e && (e.code === 'auth/wrong-password' || e.code === 'auth/invalid-credential')) { msg.textContent = 'Mevcut şifren hatalı.'; }
      else if (e && e.code === 'auth/weak-password') { msg.textContent = 'Yeni şifre en az 6 karakter olmalı.'; }
      else if (e && e.code === 'auth/too-many-requests') { msg.textContent = 'Çok fazla yanlış deneme yapıldı, biraz sonra tekrar dene.'; }
      else { msg.textContent = 'Şifre değiştirilemedi: internetini kontrol edip tekrar dene.'; }
      return;
    }
  } else {
    if (users[idx].pass !== simpleHash(eski)) { msg.textContent = 'Mevcut şifren hatalı.'; return; }
  }

  users[idx].pass = simpleHash(yeni);
  currentUser.pass = users[idx].pass;
  if (cloud.on) {
    const tamam = await cloudSaveUser(users[idx]);
    if (!tamam) { msg.textContent = 'Şifre buluta kaydedilemedi: internetini kontrol edip tekrar dene.'; return; }
  } else {
    saveUsers(users);
  }
  msg.style.color = 'var(--green)';
  msg.textContent = '✅ Şifren güncellendi.';
  document.getElementById('pfEskiSifre').value = '';
  document.getElementById('pfYeniSifre').value = '';
  document.getElementById('pfYeniSifreTekrar').value = '';
}

async function restoreSession() {
  let id = null;
  try { id = vgGetItem(SESSION_KEY) || sessionStorage.getItem(SESSION_KEY); } catch(e){}
  if (!id) return false;
  // Tüm kullanıcı listesini çekmek yerine (yüzlerce öğrenci varsa pahalı olur),
  // buluttayken doğrudan tek bir kaydı okuyoruz — her uygulama açılışında
  // gereksiz yere binlerce satır okunmasını engeller.
  let user;
  if (cloud.on) {
    user = await cloudLoadDoc('users', id);
  } else {
    user = getUsers().find(u => u.id === id);
  }
  if (!user) { try { vgRemoveItem(SESSION_KEY); sessionStorage.removeItem(SESSION_KEY); } catch(e){} return false; }
  const ilgiliOgrenciId = user.role === 'ogrenci' ? user.id : (user.role === 'veli' ? user.studentId : null);
  if (ilgiliOgrenciId && !ogrenciAyariGetir(ilgiliOgrenciId, 'appAcik')) {
    try { vgRemoveItem(SESSION_KEY); sessionStorage.removeItem(SESSION_KEY); } catch(e){}
    return false;
  }
  currentUser = user;
  return true;
}

// Giriş sonrası rolüne göre yönlendirme
function yuklemeGoster() {
  const el = document.getElementById('yuklemeEkrani');
  if (el) el.style.display = 'flex';
}
function yuklemeGizle() {
  const el = document.getElementById('yuklemeEkrani');
  if (el) el.style.display = 'none';
}
// ============================================================
//  ⚠️ KRİTİK VERİ GÜVENLİĞİ NOTU (enterApp / startApp)
//  Eskiden: cloudLoadDoc(), hem "bu öğrencinin buluttaki kaydı gerçekten yok" hem de
//  "ağ hatası/zaman aşımı nedeniyle okunamadı" durumlarında AYNI ŞEKİLDE null dönüyordu.
//  enterApp() bu iki durumu ayıramadığı için, internet yavaşlığı/kesintisi yüzünden
//  mevcut (aylarca veri girmiş) bir öğrencinin kaydı okunamadığında, öğrenciye SIFIRDAN
//  "İlk Kurulum" (setupScreen) ekranı gösteriliyordu. Öğrenci bu ekranı "bilgilerimi
//  güncelle" sanıp doldurup "Başla" derse, startApp() → saveState() BOŞ bir profili
//  buluta yazıp öğrencinin GERÇEK verisinin ÜZERİNE YAZIYOR ve geri dönüşü olmayan bir
//  veri kaybına yol açıyordu ("sanki yeni öğrenciymiş gibi, tüm verisi silinmiş" hatası
//  buradan kaynaklanıyordu).
//  ÇÖZÜM: Bulut okuması sırasında bir HATA/ZAMAN AŞIMI olduysa (ogrenciBulutDurumBelirsiz),
//  bu ASLA "yeni öğrenci" olarak yorumlanmaz — bunun yerine bağlantı hatası ekranı
//  gösterilip yeniden denemesi istenir. "İlk Kurulum" ekranı SADECE bulut açıkken
//  okuma başarıyla tamamlanıp kayıt gerçekten bulunamadığında, ya da bulut hiç
//  kullanılmıyorsa (tamamen yerel/çevrimdışı mod) gösterilir.
// ============================================================
let ogrenciBulutDurumBelirsiz = false;

async function enterApp() {
  document.getElementById('authScreen').style.display = 'none';
  yuklemeGoster();
  ogrenciBulutDurumBelirsiz = false;

  // Bulut modunda: role göre gerekli verileri önceden indir.
  // Bu işlem ne olursa olsun uygulamayı SONSUZA KADAR bekletmesin diye
  // tamamına 10 saniyelik bir güvenlik sınırı koyuyoruz — süre dolarsa
  // elde ne varsa onunla devam ederiz (veriler daha sonra kendiliğinden
  // tazelenir), ama ekran asla donmuş kalmaz.
  if (cloud.on) {
    const yukleme = (async () => {
      cloud.videolar = (await cloudLoadDoc('genel', 'videolar')) || {};
      await cloudRefreshMesajlar();
      if (currentUser.role === 'ogrenci') {
        try {
          const doc = await cloud.db.collection('states').doc(currentUser.id).get();
          cloud.states[currentUser.id] = doc.exists ? doc.data() : null;
        } catch(e) {
          console.warn('Öğrenci verisi okunamadı (ağ/izin hatası):', e);
          ogrenciBulutDurumBelirsiz = true; // var mı yok mu bilmiyoruz -- ASLA "yeni öğrenci" sayma
        }
        cloud.programs[currentUser.id] = await cloudLoadDoc('programs', currentUser.id);
      } else {
        await cloudRefreshUsers();
        const ids = (currentUser.role === 'ogretmen')
          ? getUsers().filter(u => u.role === 'ogrenci' && u.teacherId === currentUser.id).map(u => u.id)
          : (currentUser.studentId ? [currentUser.studentId] : []);
        for (const id of ids) {
          cloud.states[id]   = await cloudLoadDoc('states', id);
          cloud.programs[id] = await cloudLoadDoc('programs', id);
        }
      }
    })();
    let zamanAsimiOldu = false;
    try {
      await Promise.race([
        yukleme,
        new Promise(resolve => setTimeout(() => { zamanAsimiOldu = true; resolve(); }, 10000))
      ]);
    } catch(e) { console.warn('Bulut verisi yüklenirken sorun oluştu:', e); ogrenciBulutDurumBelirsiz = true; }
    if (zamanAsimiOldu && currentUser.role === 'ogrenci') ogrenciBulutDurumBelirsiz = true;
  }
  yuklemeGizle();

  if (currentUser.role === 'ogrenci') {
    const yerelYedekVarMi = !!vgGetItem(stateKey());
    if (loadState() && state.student.name) {
      if (!state.sb) state.sb = sbVarsayilanState();
      if (!state.vg) state.vg = {};
      sbState = state.sb;
      showApp();
    } else if (cloud.on && ogrenciBulutDurumBelirsiz && !yerelYedekVarMi) {
      // Bulut verisi okunamadı/zaman aşımına uğradı VE bu cihazda yerel bir yedek de yok.
      // Öğrencinin gerçekten yeni mi, yoksa sadece bağlantı sorunu mu yaşadığı belirsiz --
      // bu yüzden asla boş "İlk Kurulum" ekranını göstermiyoruz.
      renderBulutBaglantiHatasi();
    } else {
      if (!state.sb) state.sb = sbVarsayilanState();
      if (!state.vg) state.vg = {};
      sbState = state.sb;
      state.student.name = currentUser.name; // adı kayıttan al
      document.getElementById('setupScreen').style.display = 'block';
      const inp = document.getElementById('inputName');
      if (inp) inp.value = currentUser.name;
    }
  } else {
    renderRolePanel();
  }
}

// Bulut verisi okunamadığında (ör. internet kesintisi) gösterilen güvenli bekleme ekranı.
// "İlk Kurulum" ekranının yerine geçer; kullanıcı asla yanlışlıkla profilini sıfırdan
// dolduramaz -- sadece internetini kontrol edip tekrar deneyebilir.
function renderBulutBaglantiHatasi() {
  const el = document.getElementById('authScreen');
  el.style.display = 'block';
  el.innerHTML = `
    <div style="min-height:100vh;display:flex;align-items:center;justify-content:center;padding:20px;">
      <div class="setup-card" style="text-align:center;max-width:380px;">
        <div style="font-size:2.5rem;margin-bottom:10px;">📡</div>
        <h2 style="font-family:'Playfair Display',serif;color:var(--accent);margin-bottom:10px;">Verilerine Ulaşılamadı</h2>
        <p style="color:var(--text2);font-size:0.92rem;margin-bottom:20px;line-height:1.5;">
          İnternet bağlantısı zayıf olduğu için kayıtlı verilerin şu an güvenli şekilde yüklenemedi.
          Endişelenme, verilerin kaybolmadı — bağlantın düzelince tekrar dene.
        </p>
        <button class="btn-primary" style="width:100%;" onclick="location.reload()">🔄 Tekrar Dene</button>
      </div>
    </div>`;
}

// Veli & Öğretmen paneli
let tv = { view: 'home', studentId: null, sub: null, analiz: null };

function renderRolePanel() {
  let panel = document.getElementById('rolePanel');
  if (!panel) {
    panel = document.createElement('div');
    panel.id = 'rolePanel';
    document.body.appendChild(panel);
  }
  panel.style.display = 'block';
  const m = ROLE_META[currentUser.role];
  let inner = '';

  if (currentUser.role === 'ogretmen') {
    inner = renderTeacherView();
  } else { // veli
    const users = getUsers();
    const teacher = users.find(u => u.id === currentUser.teacherId);
    const ogr = users.find(u => u.id === currentUser.studentId);

    if (tv.view === 'mesajlar') {
      inner = renderMesajlarHub();
    } else if (tv.view === 'mesajYaz') {
      inner = renderMesajYaz();
    } else if (tv.view === 'mesajGelen') {
      inner = renderMesajKutusu('gelen');
    } else if (tv.view === 'mesajGiden') {
      inner = renderMesajKutusu('giden');
    } else if ((tv.view === 'analiz' || tv.view === 'student') && ogr) {
      inner = `<button class="btn-link" onclick="tvGo('home')" style="text-align:left;margin:0 0 12px;">← Geri</button>` + renderAnaliz(ogr);
    } else {
      const okunmamis = mesajOkunmamisSayisi();
      inner = `
        <h2 style="font-family:'Playfair Display',serif;color:var(--accent);margin-bottom:4px;">${m.icon} ${currentUser.name}</h2>
        <p style="color:var(--text3);font-size:0.85rem;margin-bottom:20px;">Veli Paneli · Rehber Öğretmen: <b>${teacher ? teacher.name : '—'}</b></p>
        <h3 style="font-size:1rem;margin-bottom:10px;">🎓 Öğrencim</h3>
        ${ogr ? `<div class="panel-list-item"><div><div class="pname">${ogr.name}</div><div class="pmeta">${ogr.email} · ${ogr.phone}</div>${studentOzet(ogr)}</div></div>`
              : '<div class="pmeta">Kayıtlı öğrenci bağlantısı bulunamadı.</div>'}
        <div style="display:flex;flex-direction:column;gap:10px;margin-top:18px;">
          <button class="btn-primary" ${ogr ? `onclick="tvGo('analiz','${ogr.id}')"` : 'disabled'} style="background:var(--accent);">📊 Başarı Analizi</button>
          <button class="btn-primary" style="background:#8b5cf6;position:relative;" onclick="mesajGit('mesajlar')">
            ✉️ Mesajlar ${okunmamis > 0 ? `<span style="background:var(--red);color:#fff;border-radius:10px;padding:1px 7px;font-size:0.72rem;margin-left:6px;">${okunmamis}</span>` : ''}
          </button>
        </div>
      `;
    }
  }

  panel.innerHTML = `
    <div style="min-height:100vh;background:var(--bg);padding:20px;">
      <div style="max-width:${tv.sub === 'program' ? '1100px' : '720px'};margin:0 auto;">
        <div class="setup-card" style="max-width:none;">
          ${inner}
          <button class="btn-link" onclick="cikisOnayla()" style="margin-top:24px;color:var(--red);">🚪 Çıkış Yap</button>
        </div>
      </div>
    </div>`;
}

function tvGo(view, studentId, sub, analiz) {
  tv = { view: view || 'list', studentId: studentId !== undefined ? studentId : tv.studentId, sub: sub || null, analiz: analiz || null };
  renderRolePanel();
}

function tvSetAylikAy(studentId, ay) {
  tv = { view: 'student', studentId: studentId, sub: 'analiz', analiz: 'aylikRapor', ay: ay };
  renderRolePanel();
}

// ---------- ÖĞRENCİNİN KENDİ "BAŞARI ANALİZİM" EKRANINI ÖDÜNÇ GÖSTERME ----------
// Rehber öğretmen / veli, öğrencinin premium Başarı Analizim ekranını (Hedefime Yaklaşma Oranım,
// Genel Durumum, Derslerim, Denemelerim, Branş Denemelerim) birebir aynı şekilde görebilsin diye
// global `state`i geçici olarak o öğrencinin verisiyle değiştirip #mainContent'i ödünç kullanır.
let tvAnalizBorrow = null; // { savedState } aktifken dolu
function tvOgrenciAnalizGoster(studentId) {
  const s = getStudentState(studentId);
  if (!s) { alert('Bu öğrencinin henüz kayıtlı bir uygulama verisi yok.'); return; }
  tvAnalizBorrow = { savedState: state, savedSbState: sbState };
  state = s;
  if (!state.kisisel) state.kisisel = {};
  if (!state.kazanimlar) state.kazanimlar = {};
  if (!state.denemeler) state.denemeler = {};
  if (!state.sb) state.sb = sbVarsayilanState();
  if (!state.vg) state.vg = {};
  sbState = state.sb; // Soru Bankası istatistikleri de bu öğrenciye ait olsun
  state.currentTab = 'grafik';
  baState = { view: null };
  baDersState = { sinav: null, ders: null };
  baBransState = { test: null };
  document.getElementById('rolePanel').style.display = 'none';
  document.getElementById('mainApp').classList.add('active');
  renderGrafik(document.getElementById('mainContent'));
  injectBackButton();
}
function tvAnalizGeriDon() {
  if (!tvAnalizBorrow) return;
  state = tvAnalizBorrow.savedState;
  sbState = tvAnalizBorrow.savedSbState;
  tvAnalizBorrow = null;
  document.getElementById('mainApp').classList.remove('active');
  document.getElementById('rolePanel').style.display = 'block';
  renderRolePanel();
}

// ---------- REHBER ÖĞRETMEN: ÖĞRENCİNİN "VERİ GİRİŞİ" EKRANINI AÇIP DÜZENLEME ----------
// Öğretmen, öğrencinin kendi cihazında gördüğü Veri Girişi ekranının birebir aynısını açar
// ve dilerse üzerinde değişiklik yapıp kaydedebilir. `state` VE `currentUser` geçici olarak
// o öğrenciye çevrilir ki yapılan her kayıt (vgSetItem -> saveState) doğru öğrencinin
// states/{studentId} dokümanına gitsin — öğretmenin kendi hesabı asla etkilenmez.
let tvVgBorrow = null; // { savedState, savedSbState, savedCurrentUser } aktifken dolu
function tvOgrenciVeriGirisiAc(studentId) {
  const s = getStudentState(studentId);
  if (!s) { alert('Bu öğrencinin henüz kayıtlı bir uygulama verisi yok.'); return; }
  const users = getUsers();
  const ogrenciUser = users.find(u => u.id === studentId) || {};
  tvVgBorrow = { savedState: state, savedSbState: sbState, savedCurrentUser: currentUser };
  state = s;
  if (!state.kisisel) state.kisisel = {};
  if (!state.kazanimlar) state.kazanimlar = {};
  if (!state.denemeler) state.denemeler = {};
  if (!state.sb) state.sb = sbVarsayilanState();
  if (!state.vg) state.vg = {};
  if (!state.bildirimler) state.bildirimler = [];
  if (!state.kavanoz) state.kavanoz = { fotograflar: [], sorular: [] };
  sbState = state.sb;
  // currentUser'ı geçici olarak bu öğrenciye çevir (id kritik: saveState buna göre kaydediyor)
  currentUser = Object.assign({}, ogrenciUser, { id: studentId, role: 'ogrenci' });
  state.currentTab = 'veriGirisi';
  vgState = { menu: null };
  document.getElementById('rolePanel').style.display = 'none';
  document.getElementById('mainApp').classList.add('active');
  renderVeriGirisi(document.getElementById('mainContent'));
}
function tvVgGeriDon() {
  if (!tvVgBorrow) return;
  // Öğretmenin az önce bu öğrenci için girdiği veri (ör. bir konunun doğru/yanlış sayısı),
  // öğretmen kendi ekranına dönerken buluta gitmeyi 1 saniye bekleyip kaybolmasın diye hemen gönderilir.
  cloudFlushAllPending();
  state = tvVgBorrow.savedState;
  sbState = tvVgBorrow.savedSbState;
  currentUser = tvVgBorrow.savedCurrentUser;
  tvVgBorrow = null;
  document.getElementById('mainApp').classList.remove('active');
  document.getElementById('rolePanel').style.display = 'block';
  renderRolePanel();
}

// ---------- MESAJLAR (Veli / Öğretmen ortak ekranlar) ----------
function mesajGit(view) {
  tv.view = view;
  renderRolePanel();
}

function renderMesajlarHub() {
  const okunmamis = mesajOkunmamisSayisi();
  return `
    <button class="btn-link" onclick="tvGo('home')" style="text-align:left;margin:0 0 12px;">← Ana Sayfa</button>
    <h3 style="font-size:1rem;margin-bottom:14px;">✉️ Mesajlar</h3>
    <div style="display:flex;flex-direction:column;gap:10px;">
      <button class="btn-primary" onclick="mesajGit('mesajYaz')">✍️ Mesaj Yaz</button>
      <button class="btn-primary" style="background:var(--green);position:relative;" onclick="mesajGit('mesajGelen')">
        📥 Gelen Kutusu ${okunmamis > 0 ? `<span style="background:var(--red);color:#fff;border-radius:10px;padding:1px 7px;font-size:0.72rem;margin-left:6px;">${okunmamis}</span>` : ''}
      </button>
      <button class="btn-primary" style="background:#8b5cf6;" onclick="mesajGit('mesajGiden')">📤 Giden Kutusu</button>
    </div>`;
}

function renderMesajYaz() {
  const aliciler = mesajAliciListesi();
  return `
    <button class="btn-link" onclick="mesajGit('mesajlar')" style="text-align:left;margin:0 0 12px;">← Mesajlar</button>
    <h3 style="font-size:1rem;margin-bottom:14px;">✍️ Mesaj Yaz</h3>
    ${aliciler.length ? `
    <div class="form-group">
      <label>Alıcı</label>
      <select id="mesajAlici">${aliciler.map(a => `<option value="${a.id}|${a.role}|${a.name}">${a.etiket}</option>`).join('')}</select>
    </div>
    <div class="form-group">
      <label>Mesajın</label>
      <textarea autocomplete="off" id="mesajMetin" rows="5" placeholder="Mesajını yaz..."></textarea>
    </div>
    <div id="mesajGonderMsg" class="pmeta" style="min-height:16px;margin-bottom:6px;"></div>
    <button class="btn-primary" onclick="mesajGonderTikla()">📨 Gönder</button>
    ` : '<div class="pmeta">Mesaj gönderebileceğin bir kişi bulunamadı.</div>'}
  `;
}

function mesajGonderTikla() {
  const sel = document.getElementById('mesajAlici');
  const metinEl = document.getElementById('mesajMetin');
  const msgEl = document.getElementById('mesajGonderMsg');
  if (!sel || !sel.value) { msgEl.textContent = 'Lütfen bir alıcı seç.'; return; }
  const metin = metinEl.value;
  if (!metin || !metin.trim()) { msgEl.textContent = 'Lütfen bir mesaj yaz.'; return; }
  const [id, role, name] = sel.value.split('|');
  const basarili = mesajGonder(id, role, name, metin);
  if (!basarili) { msgEl.textContent = 'Bu mesaj gönderilemedi.'; return; }
  msgEl.textContent = '✅ Mesaj gönderildi.';
  metinEl.value = '';
}

function renderMesajKutusu(tip) {
  const liste = mesajKutusu(tip);
  if (tip === 'gelen') mesajlariOkunduIsaretle();
  const baslik = tip === 'gelen' ? '📥 Gelen Kutusu' : '📤 Giden Kutusu';
  return `
    <button class="btn-link" onclick="mesajGit('mesajlar')" style="text-align:left;margin:0 0 12px;">← Mesajlar</button>
    <h3 style="font-size:1rem;margin-bottom:14px;">${baslik}</h3>
    ${liste.length ? liste.map(m => `
      <div style="background:var(--surface2);border:1px solid var(--border);border-radius:14px;padding:12px 14px;margin-bottom:10px;">
        <div style="display:flex;justify-content:space-between;font-size:0.78rem;color:var(--text3);margin-bottom:4px;gap:10px;">
          <span>${tip==='gelen' ? '👤 ' + m.fromName : '➡️ ' + m.toName}</span>
          <span>${new Date(m.tarih).toLocaleString('tr-TR')}</span>
        </div>
        <div style="font-size:0.9rem;white-space:pre-wrap;">${(m.mesaj || '').replace(/</g,'&lt;')}</div>
      </div>
    `).join('') : `<div class="pmeta">${tip === 'gelen' ? 'Gelen mesaj yok.' : 'Giden mesaj yok.'}</div>`}
  `;
}

// ---------- MESAJLAR (Öğrenci ekranı - dashboard kartından açılır) ----------
let ogrMesajGorunum = 'hub'; // 'hub' | 'yaz' | 'gelen' | 'giden'
function ogrMesajGit(view) {
  ogrMesajGorunum = view;
  renderTab('mesajlarim');
}
function ogrMesajGonderTikla() {
  const sel = document.getElementById('ogrMesajAlici');
  const metinEl = document.getElementById('ogrMesajMetin');
  const msgEl = document.getElementById('ogrMesajGonderMsg');
  if (!sel || !sel.value) { msgEl.textContent = 'Lütfen bir alıcı seç.'; return; }
  const metin = metinEl.value;
  if (!metin || !metin.trim()) { msgEl.textContent = 'Lütfen bir mesaj yaz.'; return; }
  const [id, role, name] = sel.value.split('|');
  const basarili = mesajGonder(id, role, name, metin);
  if (!basarili) { msgEl.textContent = 'Bu mesaj gönderilemedi.'; return; }
  msgEl.textContent = '✅ Mesaj gönderildi.';
  metinEl.value = '';
}
function renderMesajlarOgrenci(el) {
  const okunmamis = mesajOkunmamisSayisi();
  let icerik = '';

  if (ogrMesajGorunum === 'yaz') {
    const aliciler = mesajAliciListesi();
    icerik = `
      <button class="btn-link" onclick="ogrMesajGit('hub')" style="text-align:left;margin:0 0 12px;">← Mesajlar</button>
      ${aliciler.length ? `
      <div class="kb-field">
        <label class="kb-label">Alıcı</label>
        <select class="kb-input" id="ogrMesajAlici">${aliciler.map(a => `<option value="${a.id}|${a.role}|${a.name}">${a.etiket}</option>`).join('')}</select>
      </div>
      <div class="kb-field">
        <label class="kb-label">Mesajın</label>
        <textarea autocomplete="off" class="kb-input" id="ogrMesajMetin" rows="5" placeholder="Mesajını yaz..." style="height:auto;resize:vertical;"></textarea>
      </div>
      <div id="ogrMesajGonderMsg" class="pmeta" style="min-height:16px;margin-bottom:6px;"></div>
      <button class="btn-primary" onclick="ogrMesajGonderTikla()" style="width:auto;padding:12px 24px;">📨 Gönder</button>
      ` : '<div class="pmeta">Mesaj gönderebileceğin bir kişi bulunamadı.</div>'}
    `;
  } else if (ogrMesajGorunum === 'gelen' || ogrMesajGorunum === 'giden') {
    const tip = ogrMesajGorunum === 'gelen' ? 'gelen' : 'giden';
    const liste = mesajKutusu(tip);
    if (tip === 'gelen') mesajlariOkunduIsaretle();
    icerik = `
      <button class="btn-link" onclick="ogrMesajGit('hub')" style="text-align:left;margin:0 0 12px;">← Mesajlar</button>
      ${liste.length ? liste.map(m => `
        <div style="background:var(--surface2);border:1px solid var(--border);border-radius:14px;padding:12px 14px;margin-bottom:10px;">
          <div style="display:flex;justify-content:space-between;font-size:0.78rem;color:var(--text3);margin-bottom:4px;gap:10px;">
            <span>${tip==='gelen' ? '👤 ' + m.fromName : '➡️ ' + m.toName}</span>
            <span>${new Date(m.tarih).toLocaleString('tr-TR')}</span>
          </div>
          <div style="font-size:0.9rem;white-space:pre-wrap;">${(m.mesaj || '').replace(/</g,'&lt;')}</div>
        </div>
      `).join('') : `<div class="pmeta">${tip === 'gelen' ? 'Gelen mesaj yok.' : 'Giden mesaj yok.'}</div>`}
    `;
  } else {
    icerik = `
      <div style="display:flex;flex-direction:column;gap:10px;margin-top:6px;">
        <button class="btn-primary" onclick="ogrMesajGit('yaz')">✍️ Mesaj Yaz</button>
        <button class="btn-primary" style="background:var(--green);position:relative;" onclick="ogrMesajGit('gelen')">
          📥 Gelen Mesajlar ${okunmamis > 0 ? `<span style="background:var(--red);color:#fff;border-radius:10px;padding:1px 7px;font-size:0.72rem;margin-left:6px;">${okunmamis}</span>` : ''}
        </button>
        <button class="btn-primary" style="background:#8b5cf6;" onclick="ogrMesajGit('giden')">📤 Giden Mesajlar</button>
      </div>
    `;
  }

  el.innerHTML = `
  <div class="fade-up" style="max-width:640px;">
    <div class="kb-wrap">
      <div class="kb-header">
        <button onclick="switchToTab('dashboard')" style="background:none;border:none;cursor:pointer;padding:0;display:flex;flex-shrink:0;"><img src="${GERI_TUS_ICON}" style="width:32px;height:32px;"></button>
        <div class="kb-icon">✉️</div>
        <div class="kb-title">Mesajlarım</div>
      </div>
      <div class="kb-sub">Rehber öğretmeninle mesajlaşabilirsin</div>
      ${icerik}
    </div>
  </div>`;
}

function studentOzet(o) {
  try {
    const s = getStudentState(o.id);
    if (s && s.student) {
      const denemeSayi = s.denemeler ? Object.keys(s.denemeler).length : 0;
      return `<div class="pmeta">Hedef: ${s.student.uni || '—'} / ${s.student.bolum || '—'} · Deneme: ${denemeSayi}</div>`;
    }
  } catch(e){}
  return '';
}

// ---------- ÖĞRETMEN GÖRÜNÜMLERİ ----------
function renderTeacherView() {
  const users = getUsers();
  const ogrenciler = users.filter(u => u.role === 'ogrenci' && u.teacherId === currentUser.id);

  // Ana sayfa (giriş yapılınca ilk gösterilen ekran)
  if (tv.view === 'home') {
    const okunmamis = mesajOkunmamisSayisi();
    const cloudUyari = !cloud.on ? `
      <div style="background:#fef3cd;border:1px solid #f0c14b;border-radius:12px;padding:10px 12px;margin-bottom:16px;font-size:0.76rem;color:#7a5c00;line-height:1.4;">
        ⚠️ <b>Bulut senkronizasyonu kapalı.</b> Bu cihazda sadece bu cihaza kayıtlı öğrenciler görünür. Öğrencinin kendi telefonuna kaydettiği veriler bu panelde görünmesi için Firebase yapılandırmasının tamamlanması gerekir.
      </div>` : '';
    return `
      <h2 style="font-family:'Playfair Display',serif;color:var(--accent);margin-bottom:4px;">🧑‍🏫 ${currentUser.name}</h2>
      <p style="color:var(--text3);font-size:0.85rem;margin-bottom:20px;">Rehber Öğretmen Paneli</p>
      ${cloudUyari}
      <button class="btn-primary" style="margin-bottom:12px;" onclick="tvGo('list')">👨‍🎓 Öğrencilerim (${ogrenciler.length})</button>
      <button class="btn-primary" style="background:#8b5cf6;position:relative;" onclick="mesajGit('mesajlar')">
        ✉️ Mesajlar ${okunmamis > 0 ? `<span style="background:var(--red);color:#fff;border-radius:10px;padding:1px 7px;font-size:0.72rem;margin-left:6px;">${okunmamis}</span>` : ''}
      </button>
    `;
  }

  if (tv.view === 'mesajlar') return renderMesajlarHub();
  if (tv.view === 'mesajYaz') return renderMesajYaz();
  if (tv.view === 'mesajGelen') return renderMesajKutusu('gelen');
  if (tv.view === 'mesajGiden') return renderMesajKutusu('giden');

  // Öğrenci listesi
  if (tv.view === 'list') {
    return `
      <button class="btn-link" onclick="tvGo('home')" style="text-align:left;margin:0 0 12px;">← Ana Sayfa</button>
      <h3 style="font-size:1rem;margin-bottom:10px;">👨‍🎓 Öğrencilerim (${ogrenciler.length})</h3>
      ${ogrenciler.length ? ogrenciler.map(o => `
        <div class="panel-list-item" style="cursor:pointer;" onclick="tvGo('student','${o.id}')">
          <div><div class="pname">${o.name}</div><div class="pmeta">${o.email} · ${o.phone}</div>${studentOzet(o)}</div>
          <div style="font-size:1.2rem;color:var(--text3);">›</div>
        </div>`).join('') : '<div class="pmeta">Henüz sana bağlı öğrenci yok.</div>'}
    `;
  }

  if (tv.view === 'videolar') return renderVideoYonetim();

  const o = users.find(u => u.id === tv.studentId);
  if (!o) { tv = { view: 'list' }; return renderTeacherView(); }

  // Öğrenci detay: 5 ana buton
  let head = `
    <button class="btn-link" onclick="tvGo('list')" style="text-align:left;margin:0 0 12px;">← Öğrenci Listesi</button>
    <h2 style="font-family:'Playfair Display',serif;color:var(--accent);margin-bottom:2px;">🎓 ${o.name}</h2>
    <p style="color:var(--text3);font-size:0.85rem;margin-bottom:18px;">${o.email} · ${o.phone}</p>
    <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:20px;">
      <button class="btn-primary" style="flex:1;min-width:140px;${tv.sub==='kisisel'?'':'opacity:0.75;'}" onclick="tvGo('student','${o.id}','kisisel')">📋 Kişisel Bilgiler</button>
      <button class="btn-primary" style="flex:1;min-width:140px;background:var(--blue);${tv.sub==='program'?'':'opacity:0.75;'}" onclick="tvGo('student','${o.id}','program')">📅 Ders Programı Hazırla</button>
      <button class="btn-primary" style="flex:1;min-width:140px;background:var(--accent2);${tv.sub==='analiz'?'':'opacity:0.75;'}" onclick="tvGo('student','${o.id}','analiz')">📊 Öğrenci Analiz</button>
      <button class="btn-primary" style="flex:1;min-width:140px;background:#0f766e;${tv.sub==='cozulen'?'':'opacity:0.75;'}" onclick="tvCsAc('${o.id}')">🧾 Çözülen Sorular</button>
      <button class="btn-primary" style="flex:1;min-width:140px;background:linear-gradient(135deg,#8a6a2f,#d4af5a);" onclick="tvOgrenciVeriGirisiAc('${o.id}')">✏️ Veri Girişi Düzenle</button>
      <button class="btn-primary" style="flex:1;min-width:140px;background:${ogrenciAyariGetir(o.id,'appAcik') ? '#0284c7' : '#7f1d1d'};${tv.sub==='appAyar'?'':'opacity:0.75;'}position:relative;" onclick="tvGo('student','${o.id}','appAyar')">
        🔐 App Open/Close <span style="background:${ogrenciAyariGetir(o.id,'appAcik') ? 'var(--green)' : 'var(--red)'};color:#fff;border-radius:10px;padding:1px 7px;font-size:0.68rem;margin-left:6px;">${ogrenciAyariGetir(o.id,'appAcik') ? 'ON' : 'OFF'}</span>
      </button>
      <button class="btn-primary" style="flex:1;min-width:140px;background:${ogrenciAyariGetir(o.id,'csAcik') ? '#0284c7' : '#7f1d1d'};${tv.sub==='csAyar'?'':'opacity:0.75;'}position:relative;" onclick="tvGo('student','${o.id}','csAyar')">
        🏆 ÇS Open/Close <span style="background:${ogrenciAyariGetir(o.id,'csAcik') ? 'var(--green)' : 'var(--red)'};color:#fff;border-radius:10px;padding:1px 7px;font-size:0.68rem;margin-left:6px;">${ogrenciAyariGetir(o.id,'csAcik') ? 'ON' : 'OFF'}</span>
      </button>
    </div>`;

  if (tv.sub === 'kisisel') return head + renderKisisel(o);
  if (tv.sub === 'program') return head + renderProgram(o);
  if (tv.sub === 'analiz')  return head + renderAnaliz(o);
  if (tv.sub === 'cozulen') return head + renderCozulenSorular(o);
  if (tv.sub === 'appAyar') return head + `
    <h3 style="font-size:1rem;margin-bottom:8px;">🔐 App Open/Close — ${o.name}</h3>
    <p class="pmeta" style="margin-bottom:18px;">Açık (ON) olduğunda bu öğrenci ve ona bağlı veli hesabı sisteme giriş yapabilir. Kapalı (OFF) olduğunda sadece bu öğrencinin ve velisinin girişi engellenir; diğer öğrenciler etkilenmez.</p>
    <div style="display:flex;gap:10px;">
      <button class="btn-primary" style="flex:1;background:${ogrenciAyariGetir(o.id,'appAcik') ? 'var(--green)' : 'var(--surface2)'};color:${ogrenciAyariGetir(o.id,'appAcik') ? '#fff' : 'var(--text2)'};" onclick="ogrenciAyarDegistir('${o.id}','appAcik', true)">✅ ON</button>
      <button class="btn-primary" style="flex:1;background:${!ogrenciAyariGetir(o.id,'appAcik') ? 'var(--red)' : 'var(--surface2)'};color:${!ogrenciAyariGetir(o.id,'appAcik') ? '#fff' : 'var(--text2)'};" onclick="ogrenciAyarDegistir('${o.id}','appAcik', false)">⛔ OFF</button>
    </div>`;
  if (tv.sub === 'csAyar') return head + `
    <h3 style="font-size:1rem;margin-bottom:8px;">🏆 ÇS (Çıkmış Sorular) Open/Close — ${o.name}</h3>
    <p class="pmeta" style="margin-bottom:18px;">Açık (ON) olduğunda bu öğrencinin Soru Bankası'nda "Çıkmış Sorular" seviyesi görünür ve üzerinde işlem yapılabilir. Kapalı (OFF) olduğunda bu seviye yalnızca bu öğrenciden gizlenir; diğer öğrenciler etkilenmez.</p>
    <div style="display:flex;gap:10px;">
      <button class="btn-primary" style="flex:1;background:${ogrenciAyariGetir(o.id,'csAcik') ? 'var(--green)' : 'var(--surface2)'};color:${ogrenciAyariGetir(o.id,'csAcik') ? '#fff' : 'var(--text2)'};" onclick="ogrenciAyarDegistir('${o.id}','csAcik', true)">✅ ON</button>
      <button class="btn-primary" style="flex:1;background:${!ogrenciAyariGetir(o.id,'csAcik') ? 'var(--red)' : 'var(--surface2)'};color:${!ogrenciAyariGetir(o.id,'csAcik') ? '#fff' : 'var(--text2)'};" onclick="ogrenciAyarDegistir('${o.id}','csAcik', false)">⛔ OFF</button>
    </div>`;
  return head + '<div class="pmeta">Yukarıdan bir bölüm seç.</div>';
}

// ---------- 1) KİŞİSEL BİLGİLER ----------
function renderKisisel(o) {
  const users = getUsers();
  const veliler = users.filter(u => u.role === 'veli' && (u.studentId === o.id || (!u.studentId && u.teacherId === o.teacherId)));
  const s = getStudentState(o.id);
  const k = (s && s.kisisel) || {};
  const netler = k.netler || {};

  const row = (l, v) => `<div style="display:flex;justify-content:space-between;padding:9px 0;border-bottom:1px solid var(--border);font-size:0.9rem;"><span style="color:var(--text3);">${l}</span><span style="font-weight:600;text-align:right;">${v || '—'}</span></div>`;
  const obpPuani = (() => {
    const v = parseFloat(k.obp);
    return (isNaN(v) || k.obp === '' || k.obp === undefined) ? '—' : (v * 5).toFixed(2);
  })();
  const netKeys = Object.keys(netler).filter(nk => netler[nk] !== '' && netler[nk] !== undefined && netler[nk] !== null);

  let html = `<h3 style="font-size:1rem;margin-bottom:10px;">👤 Kişisel Bilgilerim (Öğrencinin Kendi Girdiği)</h3>
    <div style="background:var(--surface2);border:1px solid var(--border);border-radius:14px;padding:6px 16px;margin-bottom:18px;">
      ${row('Ad Soyad', k.ad || (s && s.student && s.student.name) || o.name)}
      ${row('Okuduğum / Mezun Olduğum Okul', k.okul)}
      ${row('Diploma Notum', k.obp)}
      ${row('OBP Puanım', obpPuani)}
      ${row('Hazırlanacağım Testler', (k.testler && k.testler.length) ? k.testler.join(', ') : (k.kararVermedim ? 'Karar Vermedim' : ''))}
      ${row('YksPusulam Başlangıç Tarihim', k.baslangicTarih ? new Date(k.baslangicTarih + 'T12:00:00').toLocaleDateString('tr-TR') : '')}
      ${row('Hedeflediğim Üniversite', k.uni || (s && s.student && s.student.uni))}
      ${row('Hedeflediğim Bölüm', k.bolum || (s && s.student && s.student.bolum))}
    </div>
    ${netKeys.length ? `<h3 style="font-size:0.92rem;margin-bottom:8px;">🎯 Hedefimi Tutturan Son Kişinin Netleri</h3>
    <div style="background:var(--surface2);border:1px solid var(--border);border-radius:14px;padding:6px 16px;margin-bottom:18px;">
      ${netKeys.map(nk => row(nk, netler[nk])).join('')}
    </div>` : ''}
    <h3 style="font-size:1rem;margin-bottom:10px;">📋 Hesap ve Veli Bilgileri</h3>
    <div style="background:var(--surface2);border:1px solid var(--border);border-radius:14px;padding:6px 16px;margin-bottom:18px;">
      ${row('Öğrenci Kodu', ensureStudentKod(o))}
      ${row('E-posta', o.email)}
      ${row('Cep Telefonu', o.phone)}
      ${row('Kayıt Tarihi', new Date(o.createdAt).toLocaleDateString('tr-TR'))}
    </div>
    <h3 style="font-size:1rem;margin-bottom:10px;">👨‍👩‍👧 Veli Kayıt Bilgileri</h3>`;

  if (!veliler.length) {
    html += '<div class="pmeta">Bu öğrenciye bağlı veli kaydı bulunamadı.</div>';
  } else {
    html += veliler.map(v => `
      <div style="background:var(--surface2);border:1px solid var(--border);border-radius:14px;padding:6px 16px;margin-bottom:10px;">
        ${row('Ad Soyad', v.name)}
        ${row('E-posta', v.email)}
        ${row('Cep Telefonu', v.phone)}
        ${row('Kayıt Tarihi', new Date(v.createdAt).toLocaleDateString('tr-TR'))}
      </div>`).join('');
  }
  return html;
}

// ---------- 2) DERS PROGRAMI (öğrencinin kendi "Ders Programım" sistemiyle birebir aynı) ----------
// Öğretmen artık öğrencinin kendi ders programı verisini (dpOwnKey) doğrudan düzenler.
let tvDp = { on: false, draft: null, backup: null, studentId: null };
let tvDpVideoSecici = null; // { di, ii }

function tvDpRerender() { renderRolePanel(); }

async function tvDpOlustur(id) {
  // Öğrencinin bu arada koyduğu tikleri/programın son halini kaybetmemek için önce buluttan güncel kopya alınır
  try { await dpBuluttanTazele(id); } catch (e) {}
  tvDp = { on: true, draft: JSON.parse(JSON.stringify(dpGetOwn(id))), backup: null, studentId: id, mesaj: '' };
  tvDpVideoSecici = null;
  tvDpRerender();
}
// "Tikleri Sil": öğrencinin ders programında "çalıştım" diye işaretlediği TÜM kutucukların tiki kaldırılır,
// kutucuklar normal rengine döner. Kutucukların içeriği (yazı/video/link) DEĞİŞMEZ. Öğrenciye hemen kaydedilir
// (Kaydet beklenmez); öğretmenin taslaktaki kaydedilmemiş düzenlemeleri korunur, sadece taslaktaki tikler de
// kaldırılır. "Geri Al" ile tikler geri getirilebilir. Öğrenci istediği zaman yeniden tik koyabilir.
function dpTikSayisi(p) {
  let n = 0;
  ((p && p.days) || []).forEach(d => (d.items || []).forEach(it => { if (it && it.tamam) n++; }));
  return n;
}
function dpTikleriTemizle(p) {
  ((p && p.days) || []).forEach(d => (d.items || []).forEach(it => { if (it && it.tamam) delete it.tamam; }));
  return p;
}
async function tvDpTikleriSil() {
  if (!tvDp.studentId) return;
  const id = tvDp.studentId;
  try { await dpBuluttanTazele(id); } catch (e) {}
  const kayitli = JSON.parse(JSON.stringify(dpGetOwn(id)));
  const sayi = dpTikSayisi(kayitli);
  if (!sayi) {
    dpTikleriTemizle(tvDp.draft);
    tvDp.mesaj = 'Öğrencinin programında silinecek tik yok.';
    tvDpRerender();
    return;
  }
  if (!confirm('Öğrencinin ders programındaki ' + sayi + ' tik silinecek ve kutucuklar normal rengine dönecek. Emin misin?')) return;
  tvDp.backup = JSON.parse(JSON.stringify(kayitli));
  dpSaveOwn(id, dpTikleriTemizle(kayitli));
  dpTikleriTemizle(tvDp.draft);
  tvDp.mesaj = '✔️ ' + sayi + ' tik silindi. Öğrenci kutucukları yeniden işaretleyebilir. (Geri almak için "Geri Al")';
  tvDpRerender();
}
function tvDpEditKapat() {
  tvDp = { on: false, draft: null, backup: null, studentId: null };
  tvDpVideoSecici = null;
  tvDpRerender();
}
function tvDpKaydet() {
  if (!tvDp.studentId) return;
  dpSaveOwn(tvDp.studentId, tvDp.draft);
  tvDp = { on: false, draft: null, backup: null, studentId: null };
  tvDpVideoSecici = null;
  tvDpRerender();
}
function tvDpSil() {
  if (!tvDp.studentId) return;
  tvDp.backup = JSON.parse(JSON.stringify(dpGetOwn(tvDp.studentId)));
  tvDp.mesaj = '';
  const bos = dpBosProgram();
  tvDp.draft = bos;
  dpSaveOwn(tvDp.studentId, JSON.parse(JSON.stringify(bos)));
  tvDpRerender();
}
function tvDpGeriAl() {
  if (!tvDp.backup || !tvDp.studentId) { tvDpRerender(); return; }
  const geri = JSON.parse(JSON.stringify(tvDp.backup));
  tvDp.draft = geri;
  dpSaveOwn(tvDp.studentId, JSON.parse(JSON.stringify(geri)));
  tvDp.backup = null;
  tvDp.mesaj = '↩️ Geri alındı.';
  tvDpRerender();
}
function tvDpKutuEkle(di) { tvDp.draft.days[di].items.push({ tip: null, metin: '', video: '' }); tvDpRerender(); }
function tvDpKutuKaldir(di, ii) { tvDp.draft.days[di].items.splice(ii, 1); tvDpRerender(); }
function tvDpKutuYazModu(di, ii) { tvDp.draft.days[di].items[ii].tip = 'yazi'; tvDpRerender(); }
function tvDpKutuMetinKaydet(di, ii, val) {
  if (tvDp.draft.days[di] && tvDp.draft.days[di].items[ii]) tvDp.draft.days[di].items[ii].metin = val;
}
function tvDpKutuEkleModu(di, ii) { tvDpVideoSecici = { di, ii, sinav: null, dersIdx: null }; tvDpRerender(); }
function tvDpVsSinav(tur) { if (!tvDpVideoSecici) return; tvDpVideoSecici.sinav = tur; tvDpVideoSecici.dersIdx = null; tvDpRerender(); }
function tvDpVsDers(idx) { if (!tvDpVideoSecici) return; tvDpVideoSecici.dersIdx = idx; tvDpRerender(); }
function tvDpVsSec(dIdx, kIdx, vIdx) {
  const d = KV_DERSLER[dIdx]; if (!d) return;
  const k = kvKonular(d)[kIdx]; const v = kvGetVideos(d, kIdx)[vIdx]; if (!v) return;
  tvDpVideoSec(d.ad + ' — ' + k + ' (' + v.ad + ')', v.url || '');
}
function tvDpVideoSeciciKapat() { tvDpVideoSecici = null; tvDpRerender(); }
function tvDpVideoSec(baslik, url) {
  if (!tvDpVideoSecici) return;
  const { di, ii } = tvDpVideoSecici;
  tvDp.draft.days[di].items[ii].tip = 'video';
  tvDp.draft.days[di].items[ii].video = baslik;
  tvDp.draft.days[di].items[ii].url = url || '';
  tvDpVideoSecici = null;
  tvDpRerender();
}
// Serbest bağlantı ekleme: video listesindeki hazır videolarla sınırlı kalmadan
// herhangi bir bağlantı (video, PDF, makale, başka bir site vb.) eklenebilir.
let tvDpLinkSecici = null;
function tvDpKutuLinkModu(di, ii) {
  const mevcut = tvDp.draft.days[di].items[ii] || {};
  tvDpLinkSecici = { di, ii, baslikVal: mevcut.tip === 'link' ? (mevcut.link || '') : '', urlVal: mevcut.tip === 'link' ? (mevcut.url || '') : '' };
  tvDpRerender();
}
function tvDpLinkSeciciKapat() { tvDpLinkSecici = null; tvDpRerender(); }
function tvDpLinkKaydet() {
  if (!tvDpLinkSecici) return;
  const { di, ii } = tvDpLinkSecici;
  const baslik = (document.getElementById('tvDpLinkBaslik').value || '').trim();
  let url = (document.getElementById('tvDpLinkUrl').value || '').trim();
  if (!url) { document.getElementById('tvDpLinkHata').textContent = 'Lütfen bir bağlantı adresi gir.'; return; }
  if (!/^https?:\/\//i.test(url)) url = 'https://' + url;
  tvDp.draft.days[di].items[ii].tip = 'link';
  tvDp.draft.days[di].items[ii].link = baslik || url;
  tvDp.draft.days[di].items[ii].url = url;
  tvDpLinkSecici = null;
  tvDpRerender();
}
function tvDpRenderLinkEkraniIcerik() {
  const s = tvDpLinkSecici;
  return `
    <button class="btn-link" onclick="tvDpLinkSeciciKapat()" style="text-align:left;margin:0 0 12px;">← Geri</button>
    <h3 style="font-size:1rem;margin-bottom:12px;">🔗 Bağlantı Ekle</h3>
    <p class="pmeta" style="margin-bottom:10px;">Bir video, PDF, makale ya da başka herhangi bir sayfanın adresini ekleyebilirsin. Öğrenci kutucuğa dokunduğunda bu adrese yönlendirilir.</p>
    <input autocomplete="off" id="tvDpLinkBaslik" type="text" placeholder="Başlık (ör: Türev Konu Anlatımı)" value="${(s.baslikVal||'').replace(/"/g,'&quot;')}" style="width:100%;box-sizing:border-box;padding:10px;border:1px solid var(--border);border-radius:8px;font-size:0.82rem;margin-bottom:10px;">
    <input autocomplete="off" id="tvDpLinkUrl" type="text" placeholder="Bağlantı adresi (https://...)" value="${(s.urlVal||'').replace(/"/g,'&quot;')}" style="width:100%;box-sizing:border-box;padding:10px;border:1px solid var(--border);border-radius:8px;font-size:0.82rem;margin-bottom:6px;">
    <div id="tvDpLinkHata" class="auth-error" style="margin-bottom:10px;"></div>
    <button class="btn-primary" onclick="tvDpLinkKaydet()">✅ Kaydet</button>`;
}

// Konu İzle'deki tüm videoları ders ders (ve konu konu) sıralı listeler.
function tvDpRenderVideoSeciciEkrani() {
  // Modüler seçici (TYT/AYT/YDT → dersler → konular sırayla) — bkz. vsIcerik (app-part2)
  const r = vsIcerik(tvDpVideoSecici, { sinav: 'tvDpVsSinav', ders: 'tvDpVsDers', sec: 'tvDpVsSec', kapat: 'tvDpVideoSeciciKapat' });
  return `
    <button class="btn-link" onclick="${r.geri}" style="text-align:left;margin:0 0 12px;">← Geri</button>
    <h3 style="font-size:1rem;margin-bottom:12px;">${r.baslik}</h3>
    ${r.html}`;
}

function tvDpRenderOlusturEkrani(o) {
  if (tvDpVideoSecici) return tvDpRenderVideoSeciciEkrani();
  if (tvDpLinkSecici) return tvDpRenderLinkEkraniIcerik();
  const own = tvDp.draft;
  const gunlerSirali = ['Pazartesi','Salı','Çarşamba','Perşembe','Cuma','Cumartesi','Pazar'];
  const cols = own.days.map((day, di) => {
    const kutular = day.items.map((it, ii) => {
      let icerik;
      if (it.tip === 'yazi') {
        icerik = `<textarea autocomplete="off" rows="2" placeholder="Yazmak istediğini gir..." oninput="tvDpKutuMetinKaydet(${di},${ii},this.value)" style="width:100%;padding:8px;border:1px solid var(--border);border-radius:8px;font-size:0.76rem;font-family:'DM Sans',sans-serif;resize:vertical;background:var(--surface);box-sizing:border-box;">${it.metin || ''}</textarea>`;
      } else if (it.tip === 'video') {
        icerik = `<div style="font-size:0.78rem;background:var(--surface);border-radius:8px;padding:8px;display:flex;align-items:center;gap:6px;"><span>▶️</span><span>${it.video}</span></div>`;
      } else if (it.tip === 'link') {
        icerik = `<div style="font-size:0.78rem;background:var(--surface);border-radius:8px;padding:8px;display:flex;align-items:center;gap:6px;overflow:hidden;"><span>🔗</span><span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${it.link || it.url}</span></div>`;
      } else {
        icerik = `<div style="font-size:0.72rem;color:var(--text3);text-align:center;padding:6px 0;">Boş kutucuk</div>`;
      }
      const tikli = !!it.tamam;
      return `
        <div style="background:${tikli ? '#d9fbd0' : 'var(--surface2)'};border:1px solid ${tikli ? '#2ecc40' : 'var(--border)'};border-radius:10px;padding:8px;margin-bottom:6px;">
          ${tikli ? '<div style="font-size:0.66rem;font-weight:800;color:#166534;margin-bottom:4px;">✔️ Öğrenci çalıştı</div>' : ''}
          ${icerik}
          <div style="display:flex;gap:4px;margin-top:6px;">
            <button onclick="tvDpKutuYazModu(${di},${ii})" style="flex:1;font-size:0.65rem;padding:5px 2px;border-radius:6px;border:1px solid var(--border);background:var(--surface);cursor:pointer;">✏️ Yaz</button>
            <button onclick="tvDpKutuEkleModu(${di},${ii})" style="flex:1;font-size:0.65rem;padding:5px 2px;border-radius:6px;border:1px solid var(--border);background:var(--surface);cursor:pointer;">🎬 Ekle</button>
            <button onclick="tvDpKutuLinkModu(${di},${ii})" style="flex:1;font-size:0.65rem;padding:5px 2px;border-radius:6px;border:1px solid var(--border);background:var(--surface);cursor:pointer;">🔗 Link</button>
            <button onclick="tvDpKutuKaldir(${di},${ii})" style="flex:1;font-size:0.65rem;padding:5px 2px;border-radius:6px;border:1px solid var(--red);background:var(--surface);color:var(--red);cursor:pointer;">🗑️ Kaldır</button>
          </div>
        </div>`;
    }).join('');
    return `
      <div style="flex:1;min-width:150px;display:flex;flex-direction:column;">
        <div style="background:var(--accent);color:#fff;border-radius:10px;padding:8px 6px;text-align:center;font-size:0.78rem;font-weight:800;margin-bottom:8px;">${gunlerSirali[di]}</div>
        ${kutular}
        <button onclick="tvDpKutuEkle(${di})" style="border:1px dashed var(--border);background:var(--surface2);border-radius:10px;padding:8px;font-size:0.85rem;cursor:pointer;">＋ Kutucuk Ekle</button>
      </div>`;
  }).join('');

  return `
    <h3 style="font-size:1rem;margin-bottom:4px;">📅 ${o.name} — Programı Oluştur</h3>
    <div style="display:flex;gap:8px;margin-bottom:8px;">
      <button class="btn-link" onclick="tvDpEditKapat()" style="text-align:left;">← Vazgeç</button>
    </div>
    <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px;">
      <button class="btn-primary" style="flex:1;min-width:120px;background:var(--green);" onclick="tvDpKaydet()">💾 Kaydet</button>
      <button class="btn-primary" style="flex:1;min-width:120px;background:var(--red);" onclick="tvDpSil()">🗑️ Sil</button>
      <button class="btn-primary" style="flex:1;min-width:120px;background:var(--surface2);color:var(--text2);${tvDp.backup ? '' : 'opacity:0.5;'}" onclick="tvDpGeriAl()">↩️ Geri Al</button>
      <button class="btn-primary" style="flex:1;min-width:120px;background:#0f766e;" onclick="tvDpTikleriSil()">✔️ Tikleri Sil</button>
    </div>
    ${tvDp.mesaj ? `<div style="background:#ecfdf5;border:1px solid #6ee7b7;color:#065f46;border-radius:10px;padding:8px 10px;font-size:0.78rem;margin-bottom:10px;">${tvDp.mesaj}</div>` : ''}
    <p class="pmeta" style="margin-bottom:12px;">Her günün altına istediğin kadar kutucuk ekleyip yazı veya video ekleyebilirsin. Değişiklikler "Kaydet" tuşuna basana kadar kalıcı olmaz.</p>
    <div style="display:flex;gap:8px;overflow-x:auto;padding-bottom:8px;">${cols}</div>`;
}

function renderProgram(o) {
  if (tvDp.on && tvDp.studentId === o.id) return tvDpRenderOlusturEkrani(o);

  const own = dpGetOwn(o.id);
  const gunlerSirali = ['Pazartesi','Salı','Çarşamba','Perşembe','Cuma','Cumartesi','Pazar'];
  const cols = own.days.map((day, di) => {
    const kutular = (day.items || []).map(it => {
      const doluMu = (it.tip === 'yazi' && it.metin && it.metin.trim()) || (it.tip === 'video' && it.video) || (it.tip === 'link' && it.url);
      if (!doluMu) return '';
      const tamam = !!it.tamam;
      // Öğrenci "çalıştım" diye işaretlediyse fosforlu yeşil; video/link ise turkuvaz; değilse normal.
      const kutuStil = tamam
        ? 'background:#39FF14;border:1px solid #2ecc40;color:#0a3d0a;'
        : (it.tip === 'video' || it.tip === 'link')
          ? 'background:#40E0D0;border:1px solid #2bb8ac;color:#04302c;'
          : 'background:var(--surface2);border:1px solid var(--border);';
      const tikRozeti = tamam ? '<span style="margin-left:auto;">✔️</span>' : '';
      if (it.tip === 'yazi') {
        return `<div style="${kutuStil}border-radius:10px;padding:8px;font-size:0.76rem;margin-bottom:6px;white-space:pre-wrap;display:flex;align-items:flex-start;gap:6px;"><span style="flex:1;">${it.metin}</span>${tikRozeti}</div>`;
      }
      if (it.tip === 'video') {
        return `<div style="${kutuStil}border-radius:10px;padding:8px;font-size:0.76rem;margin-bottom:6px;display:flex;align-items:center;gap:6px;"><span>▶️</span><span style="flex:1;">${it.video}</span>${tikRozeti}</div>`;
      }
      return `<div onclick="window.open('${it.url.replace(/'/g, "\\'")}','_blank')" style="${kutuStil}border-radius:10px;padding:8px;font-size:0.76rem;margin-bottom:6px;display:flex;align-items:center;gap:6px;cursor:pointer;overflow:hidden;"><span>🔗</span><span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1;">${it.link || it.url}</span>${tikRozeti}</div>`;
    }).join('');
    return `
      <div style="flex:1;min-width:135px;">
        <div style="background:var(--surface2);border-radius:10px;padding:8px 6px;text-align:center;font-size:0.78rem;font-weight:700;margin-bottom:6px;">${gunlerSirali[di]}</div>
        ${kutular || '<div class="pmeta" style="text-align:center;padding:8px 0;">—</div>'}
      </div>`;
  }).join('');

  return `
    <h3 style="font-size:1rem;margin-bottom:4px;">📅 Ders Programı</h3>
    <p class="pmeta" style="margin-bottom:12px;">Öğrencinin kendi uygulamasında gördüğü program burada düzenlenir.</p>
    <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px;">
      <button class="btn-primary" style="flex:1;min-width:120px;" onclick="tvDpOlustur('${o.id}')">🆕 Oluştur</button>
      <button class="btn-primary" style="flex:1;min-width:120px;background:var(--accent2);" onclick="prgBildirimGonder('${o.id}')">🔔 Bildirim Gönder</button>
    </div>
    <div id="prgMsg_${o.id}" class="pmeta" style="min-height:16px;margin-bottom:8px;"></div>
    <div style="display:flex;gap:8px;overflow-x:auto;padding-bottom:8px;">${cols}</div>`;
}

function prgMsgGoster(id, msg) {
  const el = document.getElementById('prgMsg_' + id);
  if (el) { el.textContent = msg; setTimeout(() => { if (el) el.textContent = ''; }, 3000); }
}

// Bir öğrencinin kendi cihazındaki kayıtlı state'ine (localStorage/bulut) yazar.
// Böylece rehber öğretmenin gönderdiği bildirim, öğrenci uygulamayı açtığında görünür.
function saveStudentStateFor(id, newState) {
  if (cloud.on) {
    cloud.states[id] = newState;
    cloudSaveDocDebounced('states', id, newState);
  } else {
    try { vgSetItem('ykspusulam_' + id, JSON.stringify(newState)); } catch(e){}
  }
}

// Öğrenciye "haftalık planınız hazır" bildirimi gönderir.
function prgBildirimGonder(id) {
  const s = getStudentState(id) || {};
  if (!s.bildirimler) s.bildirimler = [];
  s.bildirimler.push({
    mesaj: 'Haftalık planınız hazır!',
    tarih: new Date().toISOString(),
    okundu: false,
    gonderen: currentUser ? currentUser.name : 'Rehber Öğretmen'
  });
  saveStudentStateFor(id, s);
  prgMsgGoster(id, '🔔 Bildirim gönderildi: "Haftalık planınız hazır!"');
}

// ---------- Ders Başarısı hesabı (öğretmen › öğrenci analiz) ----------
function dbDersBasariHesapla(s) {
  const cevaplar = (s && s.sb && s.sb.cevaplar) || {};
  // Soru Bankası: ders bazında doğru / yanlış
  const sb = {};
  if (typeof SORULAR !== 'undefined' && SORULAR) {
    const idHarita = {};
    Object.keys(cevaplar).forEach(id => { if (cevaplar[id]) idHarita[id] = cevaplar[id]; });
    SORULAR.forEach(q => {
      const c = idHarita[q.id];
      if (!c) return;
      if (!sb[q.ders]) sb[q.ders] = { d: 0, y: 0 };
      if (c === q.dogru) sb[q.ders].d++; else sb[q.ders].y++;
    });
  }
  return vgTumDersler().map(d => {
    let vd = 0, vy = 0, vb = 0, tamam = 0;
    d.kazanimlar.forEach((_, ki) => {
      const maxT = vgKonuTestSayisi(d.key, ki);
      for (let t = 1; t <= maxT; t++) {
        const v = vgSGetir(s, 'vgkz_' + d.key + '_' + ki + '_' + t);
        vd += +v.d || 0; vy += +v.y || 0; vb += +v.b || 0;
      }
      if (s && s.vg && s.vg['vgkbitti_' + d.key + '_' + ki] === '1') tamam++;
    });
    const sd = (sb[d.key] || {}).d || 0, sy = (sb[d.key] || {}).y || 0;
    const vgSoru = vd + vy + vb, sbSoru = sd + sy;
    const toplamSoru = vgSoru + sbSoru;
    const net = (vd + sd) - (vy + sy) / 4;
    const oran = toplamSoru ? Math.round(net / toplamSoru * 100) : null;
    return { key: d.key, ad: d.sinav + ' ' + d.ad, sinav: d.sinav, toplamKonu: d.kazanimlar.length, tamam,
             vgSoru, sbSoru, toplamSoru, net, oran };
  });
}
function dbDersBasarisiHtml(s) {
  const liste = dbDersBasariHesapla(s);
  const renkOf = o => o === null ? 'var(--text3)' : o >= 75 ? 'var(--green)' : o >= 50 ? 'var(--accent)' : 'var(--red)';
  let out = '';
  ['TYT', 'AYT', 'YDT'].forEach(sinav => {
    const grup = liste.filter(x => x.sinav === sinav);
    if (!grup.length) return;
    out += `<div style="font-weight:800;font-size:0.86rem;margin:${out ? 14 : 0}px 0 8px;">${sinav}</div>`;
    out += grup.map(x => `
      <div class="panel-list-item" style="align-items:center;gap:10px;">
        <div style="flex:1;min-width:0;">
          <div class="pname">${x.ad}</div>
          <div style="font-size:0.82rem;margin-top:3px;"><b>${x.tamam}/${x.toplamKonu}</b> konu tamamlandı · başarı oranı <b style="color:${renkOf(x.oran)};">${x.oran === null ? '—' : (x.oran < 0 ? '-%' + Math.abs(x.oran) : '%' + x.oran)}</b></div>
          <div class="pmeta" style="margin-top:2px;">${x.toplamSoru} soru</div>
        </div>
      </div>`).join('');
  });
  return out;
}

// ---------- 2b) ÇÖZÜLEN SORULAR (rehber öğretmen: öğrencinin verdiği cevapları inceleme) ----------
// Soru Bankası: state.sb.cevaplar[soruId] = seçilen harf (+ cevapTs / sureler).
// Denemelerim: state.denemeCevaplari['TUR_no_dersKey'] = { ts, c: { soruId: harf } } (v38'den itibaren çözülen denemeler;
// boş bırakılanlar c içinde yoktur). Eski denemelerde soru bazlı cevap tutulmadığı için yalnızca D/Y/B toplamı vardır.
let tvCs = { kaynak: null, sinav: null, ders: null, deneme: null, filtre: 'hepsi', limit: 20 };
let tvCsHarita = null;
function tvCsSoru(id) {
  if (!tvCsHarita) { tvCsHarita = {}; if (typeof SORULAR !== 'undefined') SORULAR.forEach(q => { tvCsHarita[q.id] = q; }); if (typeof DENEME_TAMAMLAYICI !== 'undefined') DENEME_TAMAMLAYICI.forEach(q => { tvCsHarita[q.id] = q; }); }
  return tvCsHarita[id];
}
function tvCsAc(id) { tvCs = { kaynak: null, sinav: null, ders: null, deneme: null, filtre: 'hepsi', limit: 20 }; tvGo('student', id, 'cozulen'); }
function tvCsYenile() { renderRolePanel(); try { window.scrollTo(0, 0); } catch (e) {} }
function tvCsKaynak(k) { tvCs.kaynak = k; tvCs.sinav = null; tvCs.ders = null; tvCs.deneme = null; tvCs.filtre = 'hepsi'; tvCs.limit = 20; tvCsYenile(); }
function tvCsSinav(sn) { tvCs.sinav = sn; tvCs.ders = null; tvCsYenile(); }
function tvCsDers(d) { tvCs.ders = d; tvCs.filtre = 'hepsi'; tvCs.limit = 20; tvCsYenile(); }
function tvCsDeneme(k) { tvCs.deneme = k; tvCs.filtre = 'hepsi'; tvCs.limit = 20; tvCsYenile(); }
function tvCsFiltre(f) { tvCs.filtre = f; tvCs.limit = 20; renderRolePanel(); }
function tvCsDaha() { tvCs.limit += 20; renderRolePanel(); }
function tvCsGeri() {
  if (tvCs.kaynak === 'sb') {
    if (tvCs.ders) tvCs.ders = null; else if (tvCs.sinav) tvCs.sinav = null; else tvCs.kaynak = null;
  } else if (tvCs.kaynak === 'deneme') {
    if (tvCs.deneme) tvCs.deneme = null; else tvCs.kaynak = null;
  }
  tvCs.filtre = 'hepsi'; tvCs.limit = 20; tvCsYenile();
}

// Soru Bankası'nda öğrencinin cevapladığı sorular → [{q, cevap, ts, sure, sonuc}]
function tvCsSbOgeler(s) {
  const sb = (s && s.sb) || {};
  const cev = sb.cevaplar || {}, ts = sb.cevapTs || {}, sure = sb.sureler || {};
  const out = [];
  Object.keys(cev).forEach(id => {
    const q = tvCsSoru(id);
    if (!q || !cev[id]) return;
    out.push({ q, cevap: cev[id], ts: ts[id] || 0, sure: sure[id] || 0, sonuc: cev[id] === q.dogru ? 'dogru' : 'yanlis' });
  });
  return out;
}
function tvCsSayilar(liste) {
  let d = 0, y = 0, b = 0;
  liste.forEach(x => { if (x.sonuc === 'dogru') d++; else if (x.sonuc === 'yanlis') y++; else b++; });
  return { d, y, b, toplam: liste.length };
}
function tvCsTarih(ts) {
  if (!ts) return '';
  const dt = new Date(ts);
  if (isNaN(dt)) return '';
  return dt.toLocaleDateString('tr-TR', { day: '2-digit', month: '2-digit', year: 'numeric' }) + ' ' + dt.toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit' });
}
function tvCsSoruKarti(it, sira) {
  const q = it.q;
  const rozet = it.sonuc === 'dogru' ? ['✅ Doğru', '#166534', '#dcfce7'] : it.sonuc === 'yanlis' ? ['❌ Yanlış', '#991b1b', '#fee2e2'] : ['⚪ Boş', '#475569', '#e2e8f0'];
  const siklar = (q.siklar || []).map(sik => {
    const dogruMu = sik.harf === q.dogru, sectiMi = sik.harf === it.cevap;
    let bg = 'var(--surface)', bd = 'var(--border)', etiket = '';
    if (dogruMu) { bg = 'rgba(22,163,74,0.12)'; bd = '#16a34a'; etiket = '<span style="font-size:0.66rem;font-weight:800;color:#166534;">✔ Doğru cevap</span>'; }
    if (sectiMi && !dogruMu) { bg = 'rgba(220,38,38,0.12)'; bd = '#dc2626'; etiket = '<span style="font-size:0.66rem;font-weight:800;color:#991b1b;">✖ Öğrencinin cevabı</span>'; }
    if (sectiMi && dogruMu) etiket = '<span style="font-size:0.66rem;font-weight:800;color:#166534;">✔ Öğrencinin cevabı (doğru)</span>';
    return `<div style="display:flex;gap:8px;align-items:flex-start;padding:8px 10px;border-radius:10px;border:1.5px solid ${bd};background:${bg};margin-bottom:5px;font-size:0.84rem;">
      <b style="min-width:18px;">${sik.harf})</b><span style="flex:1;">${sik.metin}</span>${etiket ? `<span style="flex-shrink:0;text-align:right;">${etiket}</span>` : ''}</div>`;
  }).join('');
  const meta = [q.konu || '', it.ts ? tvCsTarih(it.ts) : '', it.sure ? it.sure + ' sn' : ''].filter(Boolean).join(' · ');
  return `
    <div style="background:var(--surface2);border:1px solid var(--border);border-radius:14px;padding:12px;margin-bottom:12px;">
      <div style="display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:6px;">
        <span style="font-size:0.74rem;font-weight:800;color:var(--text3);">Soru ${sira}${q.kaynak && q.seviye === 'cikmis' ? ' · ' + q.kaynak : ''}</span>
        <span style="font-size:0.72rem;font-weight:800;padding:2px 9px;border-radius:12px;color:${rozet[1]};background:${rozet[2]};">${rozet[0]}${it.sonuc === 'yanlis' || it.sonuc === 'dogru' ? ' · cevap: ' + it.cevap : ''}</span>
      </div>
      ${meta ? `<div class="pmeta" style="margin-bottom:8px;">${meta}</div>` : ''}
      <div style="font-size:0.88rem;line-height:1.55;margin-bottom:10px;">${q.metin || ''}</div>
      ${siklar}
      <div style="font-size:0.78rem;margin:6px 0 2px;"><b>Doğru cevap: ${q.dogru}</b>${it.sonuc === 'bos' ? ' · öğrenci boş bıraktı' : ''}</div>
      ${q.aciklama ? `<details style="font-size:0.8rem;line-height:1.5;"><summary style="cursor:pointer;font-weight:700;color:var(--accent);">Açıklamayı göster</summary><div style="margin-top:6px;">${q.aciklama}</div></details>` : ''}
    </div>`;
}
function tvCsKartListesi(liste, bosVar) {
  const f = tvCs.filtre;
  const sayi = tvCsSayilar(liste);
  const chip = (k, ad, n) => `<button onclick="tvCsFiltre('${k}')" style="padding:7px 12px;border-radius:18px;border:1px solid var(--border);cursor:pointer;font-size:0.76rem;font-weight:800;${f === k ? 'background:var(--accent);color:#fff;border-color:var(--accent);' : 'background:var(--surface2);color:var(--text2);'}">${ad} (${n})</button>`;
  const filtreli = f === 'hepsi' ? liste : liste.filter(x => x.sonuc === (f === 'dogru' ? 'dogru' : f === 'yanlis' ? 'yanlis' : 'bos'));
  const goster = filtreli.slice(0, tvCs.limit);
  let html = `<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:12px;">
      ${chip('hepsi', 'Tümü', sayi.toplam)}${chip('yanlis', '❌ Yanlışlar', sayi.y)}${chip('dogru', '✅ Doğrular', sayi.d)}${bosVar ? chip('bos', '⚪ Boşlar', sayi.b) : ''}
    </div>`;
  if (!filtreli.length) html += '<div class="pmeta">Bu filtrede soru yok.</div>';
  html += goster.map((it, i) => tvCsSoruKarti(it, it.sira || (i + 1))).join('');
  if (filtreli.length > goster.length) html += `<button class="btn-primary" style="width:100%;" onclick="tvCsDaha()">Daha fazla göster (${filtreli.length - goster.length} soru daha)</button>`;
  return html;
}

function renderCozulenSorular(o) {
  const s = getStudentState(o.id);
  const baslik = (t, geri) => `<div style="display:flex;align-items:center;gap:10px;margin-bottom:12px;">${geri ? `<button class="btn-link" style="margin:0;" onclick="tvCsGeri()">← Geri</button>` : ''}<h3 style="font-size:1rem;margin:0;">${t}</h3></div>`;
  if (!s) return '<div class="pmeta">Bu öğrencinin verisi bu cihazda bulunamadı. Öğrenci veri girdiğinde burada görünecek.</div>';

  // 0) Kaynak seçimi
  if (!tvCs.kaynak) {
    const sbListe = tvCsSbOgeler(s), sbS = tvCsSayilar(sbListe);
    const dc = s.denemeCevaplari || {}, dcN = Object.keys(dc).length;
    return baslik('🧾 Çözülen Sorular — ' + o.name, false) + `
      <p class="pmeta" style="margin-bottom:12px;">Öğrencinin çözdüğü soruları ve verdiği cevapları incele.</p>
      <div class="panel-list-item" style="cursor:pointer;" onclick="tvCsKaynak('sb')"><div><div class="pname">📝 Soru Bankası</div><div class="pmeta">${sbS.toplam} soru · ✅ ${sbS.d} doğru · ❌ ${sbS.y} yanlış</div></div><div style="font-size:1.2rem;">›</div></div>
      <div class="panel-list-item" style="cursor:pointer;" onclick="tvCsKaynak('deneme')"><div><div class="pname">⏱️ Denemelerim</div><div class="pmeta">${dcN ? dcN + ' çözülmüş deneme bölümü' : 'Henüz soru bazlı kayıt yok (yeni çözülen denemelerden itibaren tutulur)'}</div></div><div style="font-size:1.2rem;">›</div></div>`;
  }

  // ── SORU BANKASI ──
  if (tvCs.kaynak === 'sb') {
    const hepsi = tvCsSbOgeler(s);
    const dersBilgi = key => { const b = kvzDersBilgi(key); return b ? { sinav: b.sinav, ad: b.ad, emoji: b.emoji } : { sinav: 'Diğer', ad: key, emoji: '📘' }; };
    // sınav seçimi
    if (!tvCs.sinav) {
      const kart = sn => {
        const l = hepsi.filter(x => dersBilgi(x.q.ders).sinav === sn), c = tvCsSayilar(l);
        return `<div class="panel-list-item" style="cursor:pointer;" onclick="tvCsSinav('${sn}')"><div><div class="pname">${sn}</div><div class="pmeta">${c.toplam ? c.toplam + ' soru · ✅ ' + c.d + ' · ❌ ' + c.y : 'Çözülen soru yok'}</div></div><div style="font-size:1.2rem;">›</div></div>`;
      };
      return baslik('📝 Soru Bankası — Bölüm Seç', true) + ['TYT', 'AYT', 'YDT'].map(kart).join('') +
        (hepsi.some(x => dersBilgi(x.q.ders).sinav === 'Diğer') ? kart('Diğer') : '');
    }
    // ders seçimi (yalnızca çözülen sorusu olan dersler)
    if (!tvCs.ders) {
      const dersKeys = (tvCs.sinav === 'Diğer' ? [...new Set(hepsi.filter(x => !kvzDersBilgi(x.q.ders)).map(x => x.q.ders))]
        : (VG_DERSLER[tvCs.sinav] || []).map(d => d.key));
      const satirlar = dersKeys.map(k => {
        const l = hepsi.filter(x => x.q.ders === k); if (!l.length) return '';
        const c = tvCsSayilar(l), b = dersBilgi(k);
        const oran = c.toplam ? Math.round(c.d / c.toplam * 100) : 0;
        return `<div class="panel-list-item" style="cursor:pointer;" onclick="tvCsDers('${k}')"><div><div class="pname">${b.emoji || '📘'} ${b.sinav} ${b.ad}</div><div class="pmeta">${c.toplam} soru · ✅ ${c.d} · ❌ ${c.y} · doğru oranı %${oran}</div></div><div style="font-size:1.2rem;">›</div></div>`;
      }).join('');
      return baslik('📝 ' + tvCs.sinav + ' — Ders Seç', true) + (satirlar || '<div class="pmeta">Bu bölümde çözülmüş soru yok.</div>');
    }
    // soru listesi
    const b = dersBilgi(tvCs.ders);
    const liste = hepsi.filter(x => x.q.ders === tvCs.ders).sort((x, y) => (y.ts || 0) - (x.ts || 0));
    return baslik('📝 ' + b.sinav + ' ' + b.ad + ' — Çözülen Sorular', true) +
      '<div class="pmeta" style="margin-bottom:10px;">En son çözülen en üstte.</div>' + tvCsKartListesi(liste, false);
  }

  // ── DENEMELERİM ──
  const dc = s.denemeCevaplari || {};
  const adBul = (tur, no, dk) => {
    const bol = (tur === 'TYT' ? DENEME_TYT_BOLUM : tur === 'YDT' ? DENEME_YDT_BOLUM : Object.keys(DENEME_AYT_BOLUM).reduce((a, k) => a.concat(DENEME_AYT_BOLUM[k].altDersler), [])).find(x => x.key === dk);
    return tur + ' ' + denemeAdi(+no) + ' · ' + (bol ? bol.ad : dk);
  };
  const ayir = k => { const p = k.split('_'); return { tur: p[0], no: p[1], dk: p.slice(2).join('_') }; };
  if (!tvCs.deneme) {
    const anahtarlar = Object.keys(dc).sort((a, b) => (dc[b].ts || 0) - (dc[a].ts || 0));
    const satirlar = anahtarlar.map(k => {
      const { tur, no, dk } = ayir(k);
      const sorular = denemeSoruGetir(tur, +no, dk), c = dc[k].c || {};
      let d = 0, y = 0;
      sorular.forEach(q => { if (c[q.id]) { if (c[q.id] === q.dogru) d++; else y++; } });
      return `<div class="panel-list-item" style="cursor:pointer;" onclick="tvCsDeneme('${k}')"><div><div class="pname">${adBul(tur, no, dk)}</div><div class="pmeta">${tvCsTarih(dc[k].ts)} · D ${d} · Y ${y} · B ${sorular.length - d - y} · net ${(d - y / 4).toFixed(2)}</div></div><div style="font-size:1.2rem;">›</div></div>`;
    }).join('');
    return baslik('⏱️ Denemelerim — Çözülen Bölümler', true) + (satirlar || '<div class="pmeta">Henüz soru bazlı kayıt yok. Öğrenci bu sürümden sonra bir deneme bölümünü bitirdiğinde cevapları burada görünür (daha önce çözülen denemelerde yalnızca doğru/yanlış/boş sayıları saklanmıştı).</div>');
  }
  const k = tvCs.deneme, kayit = dc[k];
  if (!kayit) { tvCs.deneme = null; return renderCozulenSorular(o); }
  const { tur, no, dk } = ayir(k);
  const cev = kayit.c || {};
  const liste = denemeSoruGetir(tur, +no, dk).map((q, i) => ({
    q, sira: i + 1, cevap: cev[q.id] || '', ts: 0, sure: 0,
    sonuc: !cev[q.id] ? 'bos' : cev[q.id] === q.dogru ? 'dogru' : 'yanlis'
  }));
  return baslik('⏱️ ' + adBul(tur, no, dk), true) + `<div class="pmeta" style="margin-bottom:10px;">${tvCsTarih(kayit.ts)} tarihinde bitirildi.</div>` + tvCsKartListesi(liste, true);
}

// ---------- 3) ÖĞRENCİ ANALİZ ----------
function renderAnaliz(o) {
  const btn = (key, label, color) => `
    <button class="btn-primary" style="flex:1;min-width:120px;background:${color};${tv.analiz===key?'':'opacity:0.7;'}"
      onclick="tvGo('student','${o.id}','analiz','${key}')">${label}</button>`;

  let html = `
    <h3 style="font-size:1rem;margin-bottom:10px;">📊 Başarı Analizim</h3>
    <button class="btn-primary" style="width:100%;background:linear-gradient(135deg,#8a6a2f,#d4af5a);margin-bottom:14px;" onclick="tvOgrenciAnalizGoster('${o.id}')">
      🌟 Başarı Analizim'i Görüntüle (Hedefime Yaklaşma, Genel Durum, Derslerim, Denemelerim, Branş Denemeleri)
    </button>
    <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:18px;">
      ${btn('dersBasarisi','🏆 Ders Başarısı','#0284c7')}
      ${btn('aylikRapor','🗓️ Aylık Rapor','#c0392b')}
    </div>`;

  const s = getStudentState(o.id);
  if (!s) return html + '<div class="pmeta">Bu öğrencinin verisi bu cihazda bulunamadı. Öğrenci bu tarayıcıdan giriş yapıp veri girdiğinde burada görünecek.</div>';

  if (tv.analiz === 'tyt' || tv.analiz === 'ayt') {
    const isAyt = tv.analiz === 'ayt';
    const denemeler = s.denemeler || {};
    const nolar = Object.keys(denemeler).sort((a,b) => a - b);
    const filtre = d => isAyt ? d.key.startsWith('ayt') : d.key.startsWith('tyt');
    let rows = '';
    nolar.forEach(no => {
      const den = denemeler[no];
      if (!den || !den.dersler) return;
      const dersRows = DENEME_DERSLER.filter(filtre).map(dd => {
        const v = den.dersler[dd.key] || {};
        const d = +v.d || 0, y = +v.y || 0, b = +v.b || 0;
        if (!d && !y && !b) return '';
        const net = (d - y / 4).toFixed(2);
        return `<tr><td style="padding:5px 8px;">${dd.ad}</td><td style="text-align:center;color:var(--green);">${d}</td><td style="text-align:center;color:var(--red);">${y}</td><td style="text-align:center;color:var(--text3);">${b}</td><td style="text-align:center;font-weight:700;">${net}</td></tr>`;
      }).join('');
      if (!dersRows) return;
      rows += `
        <div style="background:var(--surface2);border:1px solid var(--border);border-radius:14px;padding:12px;margin-bottom:10px;">
          <div style="font-weight:700;font-size:0.88rem;margin-bottom:6px;">Deneme ${no} ${den.tarih ? '· ' + den.tarih : ''}</div>
          <table style="width:100%;border-collapse:collapse;font-size:0.82rem;">
            <tr style="color:var(--text3);font-size:0.72rem;"><th style="text-align:left;padding:4px 8px;">Ders</th><th>D</th><th>Y</th><th>B</th><th>Net</th></tr>
            ${dersRows}
          </table>
        </div>`;
    });
    html += rows || `<div class="pmeta">Henüz girilmiş ${isAyt ? 'AYT' : 'TYT'} deneme sonucu yok.</div>`;
  } else if (tv.analiz === 'dersBasarisi') {
    // Ders Başarısı (rehber öğretmen): her ders "TYT Türkçe", "AYT Fizik" gibi sınav ön adıyla,
    // TYT → AYT → YDT sırasıyla listelenir. Her satırda:
    //   • tamamlanan konu / toplam konu (Veri Girişi'nde "konu bitti" işaretlenenler — vgkbitti_)
    //   • ders başarı oranı = toplam net / toplam çözülen soru (doğru + yanlış + boş)
    //     toplam çözülen soru = Veri Girişi'nde o dersin konu testlerine girilen soru (vgkz_)
    //                         + Soru Bankası'nda o dersten cevaplanan soru
    //     net = doğru − yanlış/4 (Soru Bankası'nda boş yoktur: cevap ya doğru ya yanlıştır)
    // Denemeler kasıtlı olarak dahil değildir (Başarı Analizim'deki "Toplam Soru" ile aynı kural).
    html += dbDersBasarisiHtml(s);
  } else if (tv.analiz === 'aylikRapor') {
    // Aylık Rapor: Veri Girişi'nde her test kutusuna kaydedilen son düzenleme
    // tarihine (ts) göre aylara dağılım — o ay hangi dersten hangi konudan
    // kaç soru çözüldüğünü gösterir.
    const AY_ADLARI = ['Ocak','Şubat','Mart','Nisan','Mayıs','Haziran','Temmuz','Ağustos','Eylül','Ekim','Kasım','Aralık'];
    const aySecili = tv.ay !== undefined && tv.ay !== null ? tv.ay : null;

    html += `<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:16px;">
      ${AY_ADLARI.map((ay, ai) => `
        <button class="btn-primary" style="background:${aySecili===ai ? 'var(--accent2)' : 'var(--surface2)'};color:${aySecili===ai ? '#fff' : 'var(--text2)'};padding:10px 4px;font-size:0.78rem;"
          onclick="tvSetAylikAy('${o.id}',${ai})">${ay}</button>`).join('')}
    </div>`;

    if (aySecili === null) {
      html += '<div class="pmeta">Detayını görmek için yukarıdan bir ay seç.</div>';
    } else {
      // dersAd -> konuAd -> toplam soru
      const rapor = {};
      vgTumDersler().forEach(d => {
        d.kazanimlar.forEach((konuAd, ki) => {
          const maxT = vgKonuTestSayisi(d.key, ki);
          for (let t = 1; t <= maxT; t++) {
            const v = vgSGetir(s, 'vgkz_' + d.key + '_' + ki + '_' + t);
            if (!v || !v.ts) continue;
            const tarih = new Date(v.ts);
            if (tarih.getMonth() !== aySecili) continue;
            const soru = (+v.d || 0) + (+v.y || 0) + (+v.b || 0);
            if (!soru) continue;
            // Ders adı bölüm etiketiyle ("TYT Matematik", "AYT Matematik") — aynı adlı dersler karışmasın
            const dersEtiket = d.sinav + ' ' + d.ad;
            if (!rapor[dersEtiket]) rapor[dersEtiket] = {};
            if (!rapor[dersEtiket][konuAd]) rapor[dersEtiket][konuAd] = 0;
            rapor[dersEtiket][konuAd] += soru;
          }
        });
      });
      const dersAdlari = Object.keys(rapor);
      if (!dersAdlari.length) {
        html += `<div class="pmeta">${AY_ADLARI[aySecili]} ayında Veri Girişi'ne kaydedilmiş soru bulunamadı.</div>`;
      } else {
        html += `<h4 style="font-size:0.9rem;margin-bottom:8px;">${AY_ADLARI[aySecili]} — Derse ve Konuya Göre Çözülen Soru Sayısı</h4>`;
        dersAdlari.forEach(dersAd => {
          const konular = rapor[dersAd];
          const konuAdlari = Object.keys(konular).sort((a,b) => konular[b]-konular[a]);
          const dersToplam = konuAdlari.reduce((acc,k) => acc + konular[k], 0);
          html += `<div style="background:var(--surface2);border:1px solid var(--border);border-radius:14px;padding:12px;margin-bottom:10px;">
            <div style="font-weight:700;font-size:0.88rem;margin-bottom:6px;">${dersAd} · Toplam ${dersToplam} soru</div>
            ${konuAdlari.map(k => `<div style="display:flex;justify-content:space-between;padding:5px 0;border-bottom:1px solid var(--border);font-size:0.8rem;">
              <span>${k}</span><span style="font-weight:700;">${konular[k]} soru</span>
            </div>`).join('')}
          </div>`;
        });
      }
    }
  } else {
    html += '<div class="pmeta">Yukarıdan bir analiz türü seç.</div>';
  }
  return html;
}

// ============================================================
//  SORU KAVANOZU FOTOĞRAFLARI — SADECE CİHAZDA (BULUTA GİTMEZ)
//  Öğrencinin isteğiyle: kavanozdaki fotoğraflar hiçbir zaman internete/buluta
//  yüklenmez, sadece çekildiği telefonda saklanır. Bu yüzden ayrı, cihaza özel
//  bir localStorage anahtarında tutulur ve saveState()/cloudSaveDocDebounced
//  bulut gönderiminden önce state'ten çıkarılır.
// ============================================================
function kavanozFotoLocalKey(id) { return 'ykspusulam_kavanozfoto_' + (id || 'misafir'); }
function kavanozFotoLocalYukle(id) {
  try { return JSON.parse(localStorage.getItem(kavanozFotoLocalKey(id)) || '[]'); } catch(e){ return []; }
}
function kavanozFotoLocalKaydet(id, liste) {
  try { localStorage.setItem(kavanozFotoLocalKey(id), JSON.stringify(liste || [])); return true; }
  catch(e){ return false; }
}
// state yüklendikten sonra çağrılır: fotoğrafları her zaman cihazın kendi
// deposundan okur; eski sürümden (fotoğraflar hâlâ ana state içindeyse) bir
// kereliğine yeni depoya taşır.
function kavanozFotoSenkronla(id) {
  if (!state.kavanoz) state.kavanoz = { fotograflar: [], sorular: [] };
  let local = kavanozFotoLocalYukle(id);
  if ((!local || !local.length) && state.kavanoz.fotograflar && state.kavanoz.fotograflar.length) {
    local = state.kavanoz.fotograflar;
    kavanozFotoLocalKaydet(id, local);
  }
  state.kavanoz.fotograflar = local || [];
}

// ============================================================
//  LOCAL STORAGE (kullanıcıya özel)
// ============================================================
function stateKey() {
  return currentUser ? ('ykspusulam_' + currentUser.id) : 'ykspusulam';
}
// ⚠️ NOT (Soru Kavanozu fotoğrafları için depolama düzeltmesi):
// Kavanoz fotoğrafları YUKARIDA açıklandığı gibi kendi ayrı, cihaza özel yerinde
// (kavanozFotoLocalKey / localStorage['ykspusulam_kavanozfoto_<id>']) tutulur ve state
// yüklendiğinde kavanozFotoSenkronla() tarafından HER ZAMAN oradan `state.kavanoz.fotograflar`'a
// geri yazılır. Eskiden saveState()'in YEREL (cihaz) yazması bu diziyi olduğu gibi -- STRİPLEMEDEN
// -- genel state kaydının (localStorage['ykspusulam_<id>']) içine de gömüyordu; bulut yazması
// zaten fotoğrafları çıkarıyordu ama yerel yazması çıkarmıyordu. Sonuç: her fotoğraf, telefonun
// hafızasında İKİ KEZ duruyordu -- bir kez kendi ayrı yerinde, bir kez de öğrencinin ana state
// kaydının içinde -- gereksiz yere iki katı yer kaplıyor ve cihazın depolama sınırına (localStorage
// kotası) daha çabuk çarpılmasına yol açıyordu. kavanozFotoSenkronla() her state yüklemesinde
// fotoğrafları zaten doğru yerden geri getirdiği için, ana state kaydından fotoğrafları çıkarmak
// hiçbir veri kaybına yol açmaz -- burada da (buluttakiyle birebir aynı mantıkla) çıkarıyoruz.
function saveState() {
  const stateYerelIcin = Object.assign({}, state, {
    kavanoz: { fotograflar: [], sorular: (state.kavanoz && state.kavanoz.sorular) || [] }
  });
  const ok = vgSetItem(stateKey(), JSON.stringify(stateYerelIcin));
  if (cloud.on && currentUser) {
    cloud.states[currentUser.id] = state;
    // Fotoğraflar asla buluta gönderilmez: bulut kopyasında fotoğraf dizisi boş bırakılır.
    const stateBulutIcin = Object.assign({}, state, {
      kavanoz: { fotograflar: [], sorular: (state.kavanoz && state.kavanoz.sorular) || [] }
    });
    cloudSaveDocDebounced('states', currentUser.id, stateBulutIcin);
  }
  return ok;
}
function loadState() {
  // Bulut modunda önce buluttan gelen veriyi kullan
  if (cloud.on && currentUser && cloud.states[currentUser.id]) {
    try {
      state = JSON.parse(JSON.stringify(cloud.states[currentUser.id]));
      if (!state.denemeler) state.denemeler = {};
      if (!state.kazanimlar) state.kazanimlar = {};
      if (!state.student) state.student = { name: '', bolum: '', uni: '', puanTuru: 'TYT' };
      if (!state.kavanoz) state.kavanoz = { fotograflar: [], sorular: [] };
      if (!state.bildirimler) state.bildirimler = [];
      if (!state.sb) state.sb = sbVarsayilanState();
      if (!state.vg) state.vg = {};
      if (!state.oyunSkorlari) state.oyunSkorlari = [];
      kavanozFotoSenkronla(currentUser.id);
      const validTabs = ['dashboard','sorubankasi','denemeler','grafik','veriGirisi','kisiselBilgiler','dersProgramim','konuVideolari','denemelerim','dersSayaci','puanHesaplama','soruKavanozu','meslekKesif','yksNedir','yksBilgi','soruDagilimlari','yillaraGoreSoruDagilimi','haberler','mesajlarim','egitselOyunlar'];
      if (!validTabs.includes(state.currentTab)) state.currentTab = 'dashboard';
      return true;
    } catch(e){}
  }
  let raw = vgGetItem(stateKey());
  if (raw) { 
    try { 
      const parsed = JSON.parse(raw);
      state = parsed;
      // Eksik alanları güvenli şekilde doldur
      if (!state.denemeler) state.denemeler = {};
      if (!state.kazanimlar) state.kazanimlar = {};
      if (!state.student) state.student = { name: '', bolum: '', uni: '', puanTuru: 'TYT' };
      if (!state.kavanoz) state.kavanoz = { fotograflar: [], sorular: [] };
      if (!state.bildirimler) state.bildirimler = [];
      if (!state.sb) state.sb = sbVarsayilanState();
      if (!state.vg) state.vg = {};
      if (!state.oyunSkorlari) state.oyunSkorlari = [];
      kavanozFotoSenkronla(currentUser ? currentUser.id : null);
      // Tab adını validate et
      const validTabs = ['dashboard','sorubankasi','denemeler','grafik','veriGirisi','kisiselBilgiler','dersProgramim','konuVideolari','denemelerim','dersSayaci','puanHesaplama','soruKavanozu','meslekKesif','yksNedir','yksBilgi','soruDagilimlari','yillaraGoreSoruDagilimi','haberler','mesajlarim','egitselOyunlar'];
      if (!validTabs.includes(state.currentTab)) state.currentTab = 'dashboard';
      return true; 
    } catch(e){} 
  }
  return false;
}

// ============================================================
//  INIT
// ============================================================
window.addEventListener('load', () => {
  cloudInit(); // artık hiçbir şeyi beklemiyor, hemen devam ediyoruz
  setTimeout(() => {
    document.getElementById('splash').style.opacity = '0';
    setTimeout(async () => {
      document.getElementById('splash').style.display = 'none';
      let girisVarMi = false;
      try {
        // restoreSession() bulut kontrolü yapar; ağ çok yavaşsa/takılırsa
        // açılış ekranında sonsuza kadar beklememek için 5 saniyelik bir
        // güvenlik sınırı koyuyoruz.
        girisVarMi = await Promise.race([
          restoreSession(),
          new Promise(resolve => setTimeout(() => resolve(false), 5000))
        ]);
      } catch(e) { girisVarMi = false; }
      if (girisVarMi) {
        enterApp();
      } else {
        document.getElementById('authScreen').style.display = 'block';
        showAuthStep('stepRole');
      }
    }, 300);
  }, 500);
});

function startApp() {
  // Ek güvenlik önlemi: bulut verisi okunamadığı/zaman aşımına uğradığı için "yeni öğrenci
  // olabilir mi" belirsizse, buradan asla devam ettirmeyiz -- aksi halde bu, olası GERÇEK
  // (ve aylarca birikmiş) öğrenci verisinin boş bir profille buluta yazılıp silinmesine yol açar.
  if (cloud.on && ogrenciBulutDurumBelirsiz) {
    alert('İnternet bağlantısı sorunu nedeniyle mevcut verilerin doğrulanamadı. Verilerinin güvenliği için işlem durduruldu.\n\nLütfen internet bağlantını kontrol edip uygulamayı kapatıp tekrar aç.');
    return;
  }
  const name = document.getElementById('inputName').value.trim();
  if (!name) { alert('Lütfen adını gir!'); return; }
  state.student = {
    name,
    bolum: document.getElementById('inputBolum').value.trim(),
    uni: document.getElementById('inputUni').value.trim(),
    puanTuru: document.getElementById('inputPuan').value
  };
  // Init kazanim data
  for (const ders in DERSLER) {
    if (!state.kazanimlar[ders]) state.kazanimlar[ders] = {};
    DERSLER[ders].kazanimlar.forEach((k, i) => {
      if (!state.kazanimlar[ders][i]) {
        state.kazanimlar[ders][i] = {
          calisiIdi: false,
          tests: Array.from({length: NUM_TEST}, () => ({d:'', y:'', b:''})),
          ytLink: ''
        };
      }
    });
  }
  saveState();
  document.getElementById('setupScreen').style.display = 'none';
  showApp();
}

function showApp() {
  try { vgUygulamaDenemeKayitlariniAyir(); } catch(e){}
  try { arayuzModuUygula((state && state.arayuzModu) ? state.arayuzModu : arayuzModuOku()); } catch(e){}
  document.getElementById('mainApp').classList.add('active');
  document.getElementById('topName').textContent = state.student.name;
  buildNav();
  renderTab(state.currentTab);
  if (state.currentTab !== 'dashboard') injectBackButton();
}

// ============================================================
//  NAV
// ============================================================
function buildNav() {
  const tabs = document.getElementById('navTabs');
  tabs.innerHTML = '';
  window.labels = { dashboard: '🏠 Ana Sayfa', denemeler: '📋 Denemeler', grafik: '📈 Grafikler', sorubankasi: '📝 Soru Bankası', veriGirisi: '✏️ Veri Girişi', kisiselBilgiler: '👤 Kişisel Bilgilerim', dersProgramim: '📅 Ders Programım', konuVideolari: '🎬 Konu Videoları', denemelerim: '⏱️ Denemelerim', dersSayaci: '⏲️ Ders Sayacım', puanHesaplama: '🧮 YKS Puan Hesaplama', meslekKesif: '🚪 Mesleğimi Keşfediyorum', yksNedir: '📘 YKS Nedir?', yksBilgi: '📘 YKS Nedir?', soruDagilimlari: '📊 Soru Dağılımları', yillaraGoreSoruDagilimi: '📈 Yıllara Göre Soru Dağılımı', haberler: '📰 Haberler ve Duyurular' };
  // "Ana Sayfa" tuşu kaldırıldı; sayfalar arası dönüş artık her yerde
  // tasarladığımız Geri tuşuyla (injectBackButton) sağlanıyor.
  tabs.style.display = 'none';
}

// ============================================================
//  RENDER TAB
// ============================================================
function renderTab(tab) {
  const el = document.getElementById('mainContent');
  if (tab === 'dashboard') renderDashboard(el);
  else if (tab === 'denemeler') renderDenemeler(el);
  else if (tab === 'grafik') renderGrafik(el);
  else if (tab === 'sorubankasi') renderSoruBankasi(el);
  else if (tab === 'veriGirisi') renderVeriGirisi(el);
  else if (tab === 'kisiselBilgiler') renderKisiselBilgiler(el);
  else if (tab === 'dersProgramim') renderDersProgramim(el);
  else if (tab === 'konuVideolari') renderKonuVideolari(el);
  else if (tab === 'denemelerim') renderDenemelerim(el);
  else if (tab === 'dersSayaci') renderDersSayaci(el);
  else if (tab === 'puanHesaplama') renderPuanHesaplama(el);
  else if (tab === 'soruKavanozu') renderSoruKavanozu(el);
  else if (tab === 'meslekKesif') renderMeslekKesif(el);
  else if (tab === 'yksNedir') renderYksNedir(el);
  else if (tab === 'yksBilgi') renderYksBilgi(el);
  else if (tab === 'soruDagilimlari') renderSoruDagilimlari(el);
  else if (tab === 'yillaraGoreSoruDagilimi') renderYillaraGoreSoruDagilimi(el);
  else if (tab === 'haberler') renderHaberlerDuyurular(el);
  else if (tab === 'mesajlarim') renderMesajlarOgrenci(el);
  else if (tab === 'egitselOyunlar') renderEgitselOyunlar(el);
  else if (DERSLER[tab]) renderDers(el, tab);
}

