let oyunUI = { ekran: 'ana', tur: null, sorular: [], index: 0, dogru: 0, secim: null, cevaplandi: false };

function oyunRerender() {
  const el = document.getElementById('mainContent');
  if (el) renderEgitselOyunlar(el);
}
function oyunAnaEkraniAc() {
  oyunUI = { ekran: 'ana', tur: null, sorular: [], index: 0, dogru: 0, secim: null, cevaplandi: false };
  oyunRerender();
}
function oyunHangisiDogruAc() { oyunUI.ekran = 'hangisiDogru'; oyunRerender(); }
function oyunKaristir(dizi) {
  const arr = dizi.slice();
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    const tmp = arr[i]; arr[i] = arr[j]; arr[j] = tmp;
  }
  return arr;
}

