// ============================================================
//  DERS SAYFASI
// ============================================================
function getKD(ders, idx) {
  if (!state.kazanimlar[ders]) state.kazanimlar[ders] = {};
  if (!state.kazanimlar[ders][idx]) {
    state.kazanimlar[ders][idx] = {
      calisiIdi: false,
      tests: Array.from({length: NUM_TEST}, () => ({d:'', y:'', b:''})),
      ytLink: ''
    };
  }
  return state.kazanimlar[ders][idx];
}

function renderDers(el, ders) {
  const kazanimlar = DERSLER[ders].kazanimlar;
  const renk = DERSLER[ders].renk;

  let toplamNet = 0, testCount = 0;
  kazanimlar.forEach((_,i) => {
    const kd = getKD(ders,i);
    kd.tests.forEach(t => {
      const d=+t.d||0, y=+t.y||0, b=+t.b||0;
      if(d+y+b>0){ toplamNet += d-y/4; testCount++; }
    });
  });

  el.innerHTML = `
    <div class="fade-up">
      <div style="display:flex;align-items:center;gap:12px;padding:16px 0;">
        <div style="width:10px;height:36px;background:${renk};border-radius:5px;"></div>
        <div>
          <div style="font-family:'Playfair Display',serif;font-size:1.4rem;font-weight:900;">${ders}</div>
          <div style="font-size:0.8rem;color:var(--text3);">${kazanimlar.length} kazanım · ${testCount} test girildi</div>
        </div>
      </div>
      <div class="kazanim-list" id="kazAnimList-${ders.replace(/\s/g,'_')}">
        ${kazanimlar.map((k, i) => renderKazanimCard(ders, i, k, renk)).join('')}
      </div>
    </div>
  `;
}

function renderKazanimCard(ders, idx, k, renk) {
  const kd = getKD(ders, idx);
  // hesapla
  let topD=0, topY=0, topB=0, topTs=0, netSum=0, testCount=0;
  kd.tests.forEach(t => {
    const d=+t.d||0, y=+t.y||0, b=+t.b||0;
    topD+=d; topY+=y; topB+=b; topTs+=d+y+b;
    if(d+y+b>0){ netSum+=d-y/4; testCount++; }
  });
  const pct = topTs>0 ? Math.round(topD/topTs*100) : null;
  const netOrta = testCount>0 ? (netSum/testCount).toFixed(1) : null;

  let badgeHtml = '';

  if (pct !== null) {
    const cls = pct>=75 ? 'badge-pct-good' : pct>=50 ? 'badge-pct-mid' : 'badge-pct-bad';
    badgeHtml += `<span class="kazanim-badge ${cls}" style="margin-left:4px;">%${pct}</span>`;
  }

  const safeId = `${ders}_${idx}`.replace(/[\s,()]/g,'_');

  return `
  <div class="kazanim-card ${kd.calisiIdi ? 'done' : ''}" id="kcard_${safeId}">
    <div class="kazanim-header" onclick="toggleKazanim('${safeId}')">
      <div class="kazanim-check ${kd.calisiIdi ? 'checked' : ''}" id="chk_${safeId}" title="Bu konuyu çalıştım" onclick="event.stopPropagation();toggleCalisi('${ders}',${idx},'${safeId}')">${kd.calisiIdi ? '✓' : ''}</div>
      <div class="kazanim-num">${idx+1}</div>
      <div class="kazanim-name">${k}</div>
      ${kd.ytLink ? `<a class="yt-btn" href="${kd.ytLink}" target="_blank" onclick="event.stopPropagation()">▶ Video</a>` : ''}
      ${badgeHtml}
      <div style="color:var(--text3);font-size:0.8rem;margin-left:4px;">▾</div>
    </div>
    <div class="kazanim-body" id="kbody_${safeId}">
      <!-- Toggle -->
      <div class="toggle-row">
        <div class="toggle ${kd.calisiIdi ? 'on' : ''}" id="tog_${safeId}" onclick="toggleCalisi('${ders}',${idx},'${safeId}')"></div>
        <div class="toggle-label">Bu konuyu çalıştım</div>
      </div>

      <!-- YouTube Link -->
      <div style="display:flex;gap:8px;align-items:center;padding:12px 0;border-bottom:1px solid var(--border);margin-bottom:12px;">
        <input autocomplete="off" type="url" placeholder="YouTube video linki..." 
          style="flex:1;background:var(--surface2);border:1px solid var(--border);border-radius:8px;padding:8px 12px;color:var(--text);font-family:'DM Sans',sans-serif;font-size:0.82rem;outline:none;"
          value="${kd.ytLink || ''}"
          id="ytinput_${safeId}"
          oninput="saveYT('${ders}',${idx},'${safeId}')">
        ${kd.ytLink ? `<a class="yt-btn" href="${kd.ytLink}" target="_blank">▶ Aç</a>` : ''}
      </div>

      <!-- Test tablosu -->
      <div class="test-grid-title">Test Sonuçları (D = Doğru, Y = Yanlış, B = Boş)</div>
      <div class="tests-container">
        <table class="tests-table">
          <thead>
            <tr>
              <th>Test</th>
              <th style="color:var(--green)">D</th>
              <th style="color:var(--red)">Y</th>
              <th style="color:var(--text3)">B</th>
              <th style="color:var(--accent)">Net</th>
              <th style="color:var(--text2)">%</th>
            </tr>
          </thead>
          <tbody>
            ${kd.tests.map((t,ti) => {
              const d=+t.d||0, y=+t.y||0, b=+t.b||0, ts=d+y+b;
              const net = ts>0 ? (d-y/4).toFixed(1) : '—';
              const p = ts>0 ? Math.round(d/ts*100) : '—';
              const pcls = ts>0 ? (d/ts>=0.75?'color:var(--green)':d/ts>=0.5?'color:var(--accent)':'color:var(--red)') : '';
              return `
              <tr>
                <td class="test-num">T${ti+1}</td>
                <td><input autocomplete="off" class="score-input d-input" type="number" min="0" value="${t.d}" placeholder="0" oninput="saveTest('${ders}',${idx},${ti},'d',this.value,'${safeId}')"></td>
                <td><input autocomplete="off" class="score-input y-input" type="number" min="0" value="${t.y}" placeholder="0" oninput="saveTest('${ders}',${idx},${ti},'y',this.value,'${safeId}')"></td>
                <td><input autocomplete="off" class="score-input b-input" type="number" min="0" value="${t.b}" placeholder="0" oninput="saveTest('${ders}',${idx},${ti},'b',this.value,'${safeId}')"></td>
                <td class="net-cell" id="net_${safeId}_${ti}">${net}</td>
                <td class="pct-cell" style="${pcls}" id="pct_${safeId}_${ti}">${p !== '—' ? p+'%' : '—'}</td>
              </tr>`;
            }).join('')}
          </tbody>
        </table>
      </div>

      <!-- Özet -->
      <div class="kazanim-summary" id="sum_${safeId}">
        ${buildSummary(ders, idx)}
      </div>
    </div>
  </div>`;
}

function buildSummary(ders, idx) {
  const kd = getKD(ders,idx);
  let topD=0, topY=0, topB=0, topTs=0, netSum=0, testCount=0;
  kd.tests.forEach(t => {
    const d=+t.d||0, y=+t.y||0, b=+t.b||0;
    topD+=d; topY+=y; topB+=b; topTs+=d+y+b;
    if(d+y+b>0){ netSum+=d-y/4; testCount++; }
  });
  const pct = topTs>0 ? Math.round(topD/topTs*100) : null;
  const netAvg = testCount>0 ? (netSum/testCount).toFixed(2) : null;

  return `
    <div class="sum-item">Toplam: <span>${topTs}</span></div>
    <div class="sum-item">✅ <span class="s-green">${topD}</span></div>
    <div class="sum-item">❌ <span class="s-red">${topY}</span></div>
    ${netAvg !== null ? `<div class="sum-item">Net Ort: <span class="s-accent">${netAvg}</span></div>` : ''}
    ${pct !== null ? `
      <div style="flex:1;display:flex;align-items:center;gap:8px;">
        <div class="bar-wrap"><div class="bar-fill" style="width:${pct}%;background:${pct>=75?'var(--green)':pct>=50?'var(--accent)':'var(--red)'};"></div></div>
        <span style="font-size:0.82rem;font-weight:700;color:${pct>=75?'var(--green)':pct>=50?'var(--accent)':'var(--red)'}">%${pct}</span>
      </div>` : '<div style="color:var(--text3);font-size:0.8rem;">Henüz test girilmedi</div>'}
  `;
}

function toggleKazanim(safeId) {
  const body = document.getElementById('kbody_' + safeId);
  if (body) body.classList.toggle('open');
}

function toggleCalisi(ders, idx, safeId) {
  const kd = getKD(ders, idx);
  kd.calisiIdi = !kd.calisiIdi;
  saveState();

  const card = document.getElementById('kcard_' + safeId);
  const wasOpen = !!(card && card.querySelector('.kazanim-body.open'));

  if (card && card.parentNode) {
    const html = renderKazanimCard(ders, idx, DERSLER[ders].kazanimlar[idx], DERSLER[ders].renk);
    const temp = document.createElement('div');
    temp.innerHTML = html.trim();
    const newCard = temp.firstElementChild;
    card.parentNode.replaceChild(newCard, card);
    if (wasOpen) {
      const newBody = document.getElementById('kbody_' + safeId);
      if (newBody) newBody.classList.add('open');
    }
  }
}

function saveTest(ders, idx, testIdx, field, val, safeId) {
  const kd = getKD(ders, idx);
  kd.tests[testIdx][field] = val === '' ? '' : +val;
  kd.tests[testIdx].tarih = Date.now(); // Aylık Rapor için: bu test kutusunun en son ne zaman düzenlendiği
  saveState();
  // update net & pct cell
  const t = kd.tests[testIdx];
  const d=+t.d||0, y=+t.y||0, b=+t.b||0, ts=d+y+b;
  const netEl = document.getElementById(`net_${safeId}_${testIdx}`);
  const pctEl = document.getElementById(`pct_${safeId}_${testIdx}`);
  if (netEl) netEl.textContent = ts>0 ? (d-y/4).toFixed(1) : '—';
  if (pctEl) {
    if (ts>0) {
      const p = Math.round(d/ts*100);
      pctEl.textContent = p+'%';
      pctEl.style.color = p>=75?'var(--green)':p>=50?'var(--accent)':'var(--red)';
    } else {
      pctEl.textContent = '—';
      pctEl.style.color = '';
    }
  }
  // update summary
  const sumEl = document.getElementById('sum_' + safeId);
  if (sumEl) sumEl.innerHTML = buildSummary(ders, idx);
}

function saveYT(ders, idx, safeId) {
  const input = document.getElementById('ytinput_' + safeId);
  if (!input) return;
  const kd = getKD(ders, idx);
  kd.ytLink = input.value;
  saveState();
}

